    wire wbm_64b_r_rarb_vld = (wbm_64b_r_rgnt_mem && wbm_64b_r_rarb_req[0]) || (wbm_64b_r_rgnt_l5s && wbm_64b_r_rarb_req[1]) || (wbm_64b_r_rgnt_wbs && wbm_64b_r_rarb_req[2]) || (wbm_64b_r_rgnt_subtractive && wbm_64b_r_rarb_req[3]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            wbm_64b_r_rarb_lock   <= '0;
            wbm_64b_r_rarb_rr     <= '0;
            wbm_64b_r_rarb_locked <= 1'b0;
        end else if (wbm_64b_r_rarb_vld && wbm_64b_rready) begin
            wbm_64b_r_rarb_locked <= 1'b0;
            wbm_64b_r_rarb_rr <= (wbm_64b_r_rarb_gnt == 2'd3) ? 2'd0 : wbm_64b_r_rarb_gnt + 1'b1;
        end else if (wbm_64b_r_rarb_vld) begin
            wbm_64b_r_rarb_lock   <= wbm_64b_r_rarb_gnt;       // offered, not taken: hold
            wbm_64b_r_rarb_locked <= 1'b1;
        end
    )

    // ================================================================
    // Slave 0: mem (64b)
    // ================================================================
    // Multi-master (6 masters) → mem
    //   - cpu (rw)
    //   - l4m (rw)
    //   - l5m (rw)
    //   - p4m (rw)
    //   - p5m (rw)
    //   - wbm (rw)

    wire cpu_64b_aw_to_mem = (cpu_64b_aw.addr <= 32'h0fffffff);
    wire cpu_64b_ar_to_mem = (cpu_64b_ar.addr <= 32'h0fffffff);
    wire l4m_64b_aw_to_mem = (l4m_64b_aw.addr <= 32'h0fffffff);
    wire l4m_64b_ar_to_mem = (l4m_64b_ar.addr <= 32'h0fffffff);
    wire l5m_64b_aw_to_mem = (l5m_64b_aw.addr <= 32'h0fffffff);
    wire l5m_64b_ar_to_mem = (l5m_64b_ar.addr <= 32'h0fffffff);
    wire p4m_64b_aw_to_mem = (p4m_64b_aw.addr <= 32'h0fffffff);
    wire p4m_64b_ar_to_mem = (p4m_64b_ar.addr <= 32'h0fffffff);
    wire p5m_64b_aw_to_mem = (p5m_64b_aw.addr <= 32'h0fffffff);
    wire p5m_64b_ar_to_mem = (p5m_64b_ar.addr <= 32'h0fffffff);
    wire wbm_64b_aw_to_mem = (wbm_64b_aw.addr <= 32'h0fffffff);
    wire wbm_64b_ar_to_mem = (wbm_64b_ar.addr <= 32'h0fffffff);

    // AW request slots for mem: arbitration at the slave pins
    assign cpu_64b_aw_slot_mem_in_valid = cpu_64b_aw_to_mem && cpu_64b_awvalid && !(cpu_64b_aw_hold_mem || cpu_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_aw_slot_mem_in_valid), .wr_ready(cpu_64b_aw_slot_mem_in_ready), .wr_data(cpu_64b_aw),
        .rd_valid(cpu_64b_aw_slot_mem_valid), .rd_ready(cpu_64b_aw_slot_mem_ready), .rd_data(cpu_64b_aw_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_64b_aw_slot_mem_in_valid = l4m_64b_aw_to_mem && l4m_64b_awvalid && !(l4m_64b_aw_hold_mem || l4m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l4m_64b_aw_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_64b_aw_slot_mem_in_valid), .wr_ready(l4m_64b_aw_slot_mem_in_ready), .wr_data(l4m_64b_aw),
        .rd_valid(l4m_64b_aw_slot_mem_valid), .rd_ready(l4m_64b_aw_slot_mem_ready), .rd_data(l4m_64b_aw_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l5m_64b_aw_slot_mem_in_valid = l5m_64b_aw_to_mem && l5m_64b_awvalid && !(l5m_64b_aw_hold_mem || l5m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l5m_64b_aw_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l5m_64b_aw_slot_mem_in_valid), .wr_ready(l5m_64b_aw_slot_mem_in_ready), .wr_data(l5m_64b_aw),
        .rd_valid(l5m_64b_aw_slot_mem_valid), .rd_ready(l5m_64b_aw_slot_mem_ready), .rd_data(l5m_64b_aw_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_64b_aw_slot_mem_in_valid = p4m_64b_aw_to_mem && p4m_64b_awvalid && !(p4m_64b_aw_hold_mem || p4m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p4m_64b_aw_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_64b_aw_slot_mem_in_valid), .wr_ready(p4m_64b_aw_slot_mem_in_ready), .wr_data(p4m_64b_aw),
        .rd_valid(p4m_64b_aw_slot_mem_valid), .rd_ready(p4m_64b_aw_slot_mem_ready), .rd_data(p4m_64b_aw_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_64b_aw_slot_mem_in_valid = p5m_64b_aw_to_mem && p5m_64b_awvalid && !(p5m_64b_aw_hold_mem || p5m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p5m_64b_aw_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_64b_aw_slot_mem_in_valid), .wr_ready(p5m_64b_aw_slot_mem_in_ready), .wr_data(p5m_64b_aw),
        .rd_valid(p5m_64b_aw_slot_mem_valid), .rd_ready(p5m_64b_aw_slot_mem_ready), .rd_data(p5m_64b_aw_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_64b_aw_slot_mem_in_valid = wbm_64b_aw_to_mem && wbm_64b_awvalid && !(wbm_64b_aw_hold_mem || wbm_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_wbm_64b_aw_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_64b_aw_slot_mem_in_valid), .wr_ready(wbm_64b_aw_slot_mem_in_ready), .wr_data(wbm_64b_aw),
        .rd_valid(wbm_64b_aw_slot_mem_valid), .rd_ready(wbm_64b_aw_slot_mem_ready), .rd_data(wbm_64b_aw_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for mem: round-robin, lock until handshake ----
    logic [5:0] mem_aw_arb_req;
    assign mem_aw_arb_req = {wbm_64b_aw_slot_mem_valid, p5m_64b_aw_slot_mem_valid, p4m_64b_aw_slot_mem_valid, l5m_64b_aw_slot_mem_valid, l4m_64b_aw_slot_mem_valid, cpu_64b_aw_slot_mem_valid};
    logic [2:0] mem_aw_arb_lock, mem_aw_arb_rr;
    logic mem_aw_arb_locked;
    wire [2:0] mem_aw_arb_pick = (mem_aw_arb_rr == 3'd0) ? (mem_aw_arb_req[0] ? 3'd0 : mem_aw_arb_req[1] ? 3'd1 : mem_aw_arb_req[2] ? 3'd2 : mem_aw_arb_req[3] ? 3'd3 : mem_aw_arb_req[4] ? 3'd4 : 3'd5) : 
        (mem_aw_arb_rr == 3'd1) ? (mem_aw_arb_req[1] ? 3'd1 : mem_aw_arb_req[2] ? 3'd2 : mem_aw_arb_req[3] ? 3'd3 : mem_aw_arb_req[4] ? 3'd4 : mem_aw_arb_req[5] ? 3'd5 : 3'd0) : 
        (mem_aw_arb_rr == 3'd2) ? (mem_aw_arb_req[2] ? 3'd2 : mem_aw_arb_req[3] ? 3'd3 : mem_aw_arb_req[4] ? 3'd4 : mem_aw_arb_req[5] ? 3'd5 : mem_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (mem_aw_arb_rr == 3'd3) ? (mem_aw_arb_req[3] ? 3'd3 : mem_aw_arb_req[4] ? 3'd4 : mem_aw_arb_req[5] ? 3'd5 : mem_aw_arb_req[0] ? 3'd0 : mem_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        (mem_aw_arb_rr == 3'd4) ? (mem_aw_arb_req[4] ? 3'd4 : mem_aw_arb_req[5] ? 3'd5 : mem_aw_arb_req[0] ? 3'd0 : mem_aw_arb_req[1] ? 3'd1 : mem_aw_arb_req[2] ? 3'd2 : 3'd3) : 
        mem_aw_arb_req[5] ? 3'd5 : mem_aw_arb_req[0] ? 3'd0 : mem_aw_arb_req[1] ? 3'd1 : mem_aw_arb_req[2] ? 3'd2 : mem_aw_arb_req[3] ? 3'd3 : 3'd4;
    wire mem_aw_arb_gnt_valid = mem_aw_arb_locked || (|mem_aw_arb_req);
    wire [2:0] mem_aw_arb_gnt = mem_aw_arb_locked ? mem_aw_arb_lock : mem_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem_aw_arb_lock   <= '0;
            mem_aw_arb_rr     <= '0;
            mem_aw_arb_locked <= 1'b0;
        end else begin
            if (mem_axi_awvalid && mem_axi_awready) begin
                mem_aw_arb_locked <= 1'b0;
                mem_aw_arb_rr <= (mem_aw_arb_gnt == 3'd5) ? 3'd0 : mem_aw_arb_gnt + 1'b1;
            end else if (mem_axi_awvalid) begin
                mem_aw_arb_lock   <= mem_aw_arb_gnt;
                mem_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_aw_gnt_mem = mem_aw_arb_gnt_valid && (mem_aw_arb_gnt == 3'd0) && mem_aw_arb_req[0];
    wire l4m_64b_aw_gnt_mem = mem_aw_arb_gnt_valid && (mem_aw_arb_gnt == 3'd1) && mem_aw_arb_req[1];
    wire l5m_64b_aw_gnt_mem = mem_aw_arb_gnt_valid && (mem_aw_arb_gnt == 3'd2) && mem_aw_arb_req[2];
    wire p4m_64b_aw_gnt_mem = mem_aw_arb_gnt_valid && (mem_aw_arb_gnt == 3'd3) && mem_aw_arb_req[3];
    wire p5m_64b_aw_gnt_mem = mem_aw_arb_gnt_valid && (mem_aw_arb_gnt == 3'd4) && mem_aw_arb_req[4];
    wire wbm_64b_aw_gnt_mem = mem_aw_arb_gnt_valid && (mem_aw_arb_gnt == 3'd5) && mem_aw_arb_req[5];
    assign cpu_64b_aw_slot_mem_ready = cpu_64b_aw_gnt_mem && mem_axi_awready;
    assign l4m_64b_aw_slot_mem_ready = l4m_64b_aw_gnt_mem && mem_axi_awready;
    assign l5m_64b_aw_slot_mem_ready = l5m_64b_aw_gnt_mem && mem_axi_awready;
    assign p4m_64b_aw_slot_mem_ready = p4m_64b_aw_gnt_mem && mem_axi_awready;
    assign p5m_64b_aw_slot_mem_ready = p5m_64b_aw_gnt_mem && mem_axi_awready;
    assign wbm_64b_aw_slot_mem_ready = wbm_64b_aw_gnt_mem && mem_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign mem_axi_awid = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.id : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.id : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.id : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.id : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.id : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.id : '0);
    assign mem_axi_awaddr = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.addr : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.addr : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.addr : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.addr : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.addr : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.addr : '0);
    assign mem_axi_awlen = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.len : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.len : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.len : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.len : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.len : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.len : '0);
    assign mem_axi_awsize = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.size : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.size : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.size : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.size : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.size : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.size : '0);
    assign mem_axi_awburst = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.burst : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.burst : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.burst : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.burst : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.burst : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.burst : '0);
    assign mem_axi_awlock = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.lock : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.lock : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.lock : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.lock : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.lock : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.lock : '0);
    assign mem_axi_awcache = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.cache : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.cache : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.cache : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.cache : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.cache : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.cache : '0);
    assign mem_axi_awprot = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.prot : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.prot : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.prot : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.prot : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.prot : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.prot : '0);
    assign mem_axi_awqos = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.qos : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.qos : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.qos : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.qos : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.qos : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.qos : '0);
    assign mem_axi_awregion = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.region : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.region : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.region : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.region : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.region : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.region : '0);
    assign mem_axi_awuser = (cpu_64b_aw_gnt_mem ? cpu_64b_aw_slot_mem.user : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_64b_aw_slot_mem.user : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_64b_aw_slot_mem.user : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_64b_aw_slot_mem.user : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_64b_aw_slot_mem.user : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_64b_aw_slot_mem.user : '0);
    assign mem_axi_awvalid = cpu_64b_aw_gnt_mem || l4m_64b_aw_gnt_mem || l5m_64b_aw_gnt_mem || p4m_64b_aw_gnt_mem || p5m_64b_aw_gnt_mem || wbm_64b_aw_gnt_mem;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] mem_wowner_mem [16];
    logic [4:0] mem_wowner_wptr, mem_wowner_rptr;
    logic mem_wowner_ahead;
    wire mem_wowner_valid = (mem_wowner_wptr != mem_wowner_rptr);
    wire mem_wowner_byp = !mem_wowner_valid && !mem_wowner_ahead && mem_axi_awvalid;
    wire mem_wowner_aw_hs = mem_axi_awvalid && mem_axi_awready;
    wire mem_wowner_w_end = mem_axi_wvalid && mem_axi_wready && mem_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem_wowner_wptr  <= '0;
            mem_wowner_rptr  <= '0;
            mem_wowner_ahead <= 1'b0;
        end else begin
            if (mem_wowner_aw_hs && mem_wowner_ahead) begin
                mem_wowner_ahead <= 1'b0;   // its W already went
            end else if (mem_wowner_aw_hs && !(mem_wowner_byp && mem_wowner_w_end)) begin
                mem_wowner_mem[mem_wowner_wptr[3:0]] <= mem_aw_arb_gnt;
                mem_wowner_wptr <= mem_wowner_wptr + 1'b1;
            end else if (!mem_wowner_aw_hs && mem_wowner_byp && mem_wowner_w_end) begin
                mem_wowner_ahead <= 1'b1;
            end
            if (mem_wowner_valid && mem_wowner_w_end) begin
                mem_wowner_rptr <= mem_wowner_rptr + 1'b1;
            end
        end
    )
    wire [2:0] mem_wowner_head = mem_wowner_valid ? mem_wowner_mem[mem_wowner_rptr[3:0]]
                                       : mem_aw_arb_gnt;
    assign cpu_64b_w_sel_mem = (mem_wowner_valid || mem_wowner_byp) && (mem_wowner_head == 3'd0) && cpu_64b_w_to_mem;
    assign l4m_64b_w_sel_mem = (mem_wowner_valid || mem_wowner_byp) && (mem_wowner_head == 3'd1) && l4m_64b_w_to_mem;
    assign l5m_64b_w_sel_mem = (mem_wowner_valid || mem_wowner_byp) && (mem_wowner_head == 3'd2) && l5m_64b_w_to_mem;
    assign p4m_64b_w_sel_mem = (mem_wowner_valid || mem_wowner_byp) && (mem_wowner_head == 3'd3) && p4m_64b_w_to_mem;
    assign p5m_64b_w_sel_mem = (mem_wowner_valid || mem_wowner_byp) && (mem_wowner_head == 3'd4) && p5m_64b_w_to_mem;
    assign wbm_64b_w_sel_mem = (mem_wowner_valid || mem_wowner_byp) && (mem_wowner_head == 3'd5) && wbm_64b_w_to_mem;

    // W channel (owner-gated mux across writing masters)
    assign mem_axi_wdata = ((cpu_64b_w_sel_mem && cpu_64b_wvalid) ? cpu_64b_w.data : '0) |
        ((l4m_64b_w_sel_mem && l4m_64b_wvalid) ? l4m_64b_w.data : '0) |
        ((l5m_64b_w_sel_mem && l5m_64b_wvalid) ? l5m_64b_w.data : '0) |
        ((p4m_64b_w_sel_mem && p4m_64b_wvalid) ? p4m_64b_w.data : '0) |
        ((p5m_64b_w_sel_mem && p5m_64b_wvalid) ? p5m_64b_w.data : '0) |
        ((wbm_64b_w_sel_mem && wbm_64b_wvalid) ? wbm_64b_w.data : '0);
    assign mem_axi_wstrb = ((cpu_64b_w_sel_mem && cpu_64b_wvalid) ? cpu_64b_w.strb : '0) |
        ((l4m_64b_w_sel_mem && l4m_64b_wvalid) ? l4m_64b_w.strb : '0) |
        ((l5m_64b_w_sel_mem && l5m_64b_wvalid) ? l5m_64b_w.strb : '0) |
        ((p4m_64b_w_sel_mem && p4m_64b_wvalid) ? p4m_64b_w.strb : '0) |
        ((p5m_64b_w_sel_mem && p5m_64b_wvalid) ? p5m_64b_w.strb : '0) |
        ((wbm_64b_w_sel_mem && wbm_64b_wvalid) ? wbm_64b_w.strb : '0);
    assign mem_axi_wlast = ((cpu_64b_w_sel_mem && cpu_64b_wvalid) ? cpu_64b_w.last : '0) |
        ((l4m_64b_w_sel_mem && l4m_64b_wvalid) ? l4m_64b_w.last : '0) |
        ((l5m_64b_w_sel_mem && l5m_64b_wvalid) ? l5m_64b_w.last : '0) |
        ((p4m_64b_w_sel_mem && p4m_64b_wvalid) ? p4m_64b_w.last : '0) |
        ((p5m_64b_w_sel_mem && p5m_64b_wvalid) ? p5m_64b_w.last : '0) |
        ((wbm_64b_w_sel_mem && wbm_64b_wvalid) ? wbm_64b_w.last : '0);
    assign mem_axi_wuser = ((cpu_64b_w_sel_mem && cpu_64b_wvalid) ? cpu_64b_w.user : '0) |
        ((l4m_64b_w_sel_mem && l4m_64b_wvalid) ? l4m_64b_w.user : '0) |
        ((l5m_64b_w_sel_mem && l5m_64b_wvalid) ? l5m_64b_w.user : '0) |
        ((p4m_64b_w_sel_mem && p4m_64b_wvalid) ? p4m_64b_w.user : '0) |
        ((p5m_64b_w_sel_mem && p5m_64b_wvalid) ? p5m_64b_w.user : '0) |
        ((wbm_64b_w_sel_mem && wbm_64b_wvalid) ? wbm_64b_w.user : '0);
    assign mem_axi_wvalid = (cpu_64b_w_sel_mem && cpu_64b_wvalid) || (l4m_64b_w_sel_mem && l4m_64b_wvalid) || (l5m_64b_w_sel_mem && l5m_64b_wvalid) || (p4m_64b_w_sel_mem && p4m_64b_wvalid) || (p5m_64b_w_sel_mem && p5m_64b_wvalid) || (wbm_64b_w_sel_mem && wbm_64b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign mem_axi_bready = (cpu_64b_b_rgnt_mem ? cpu_64b_bready : '0) |
        (l4m_64b_b_rgnt_mem ? l4m_64b_bready : '0) |
        (l5m_64b_b_rgnt_mem ? l5m_64b_bready : '0) |
        (p4m_64b_b_rgnt_mem ? p4m_64b_bready : '0) |
        (p5m_64b_b_rgnt_mem ? p5m_64b_bready : '0) |
        (wbm_64b_b_rgnt_mem ? wbm_64b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign mem_axi_bridge_id_aw = (cpu_64b_aw_gnt_mem ? cpu_bridge_id_aw : '0) |
        (l4m_64b_aw_gnt_mem ? l4m_bridge_id_aw : '0) |
        (l5m_64b_aw_gnt_mem ? l5m_bridge_id_aw : '0) |
        (p4m_64b_aw_gnt_mem ? p4m_bridge_id_aw : '0) |
        (p5m_64b_aw_gnt_mem ? p5m_bridge_id_aw : '0) |
        (wbm_64b_aw_gnt_mem ? wbm_bridge_id_aw : '0);

    // AR request slots for mem: arbitration at the slave pins
    assign cpu_64b_ar_slot_mem_in_valid = cpu_64b_ar_to_mem && cpu_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_64b_ar_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_ar_slot_mem_in_valid), .wr_ready(cpu_64b_ar_slot_mem_in_ready), .wr_data(cpu_64b_ar),
        .rd_valid(cpu_64b_ar_slot_mem_valid), .rd_ready(cpu_64b_ar_slot_mem_ready), .rd_data(cpu_64b_ar_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_64b_ar_slot_mem_in_valid = l4m_64b_ar_to_mem && l4m_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_l4m_64b_ar_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_64b_ar_slot_mem_in_valid), .wr_ready(l4m_64b_ar_slot_mem_in_ready), .wr_data(l4m_64b_ar),
        .rd_valid(l4m_64b_ar_slot_mem_valid), .rd_ready(l4m_64b_ar_slot_mem_ready), .rd_data(l4m_64b_ar_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l5m_64b_ar_slot_mem_in_valid = l5m_64b_ar_to_mem && l5m_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_l5m_64b_ar_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l5m_64b_ar_slot_mem_in_valid), .wr_ready(l5m_64b_ar_slot_mem_in_ready), .wr_data(l5m_64b_ar),
        .rd_valid(l5m_64b_ar_slot_mem_valid), .rd_ready(l5m_64b_ar_slot_mem_ready), .rd_data(l5m_64b_ar_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_64b_ar_slot_mem_in_valid = p4m_64b_ar_to_mem && p4m_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_p4m_64b_ar_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_64b_ar_slot_mem_in_valid), .wr_ready(p4m_64b_ar_slot_mem_in_ready), .wr_data(p4m_64b_ar),
        .rd_valid(p4m_64b_ar_slot_mem_valid), .rd_ready(p4m_64b_ar_slot_mem_ready), .rd_data(p4m_64b_ar_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_64b_ar_slot_mem_in_valid = p5m_64b_ar_to_mem && p5m_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_p5m_64b_ar_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_64b_ar_slot_mem_in_valid), .wr_ready(p5m_64b_ar_slot_mem_in_ready), .wr_data(p5m_64b_ar),
        .rd_valid(p5m_64b_ar_slot_mem_valid), .rd_ready(p5m_64b_ar_slot_mem_ready), .rd_data(p5m_64b_ar_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_64b_ar_slot_mem_in_valid = wbm_64b_ar_to_mem && wbm_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_wbm_64b_ar_slot_mem (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_64b_ar_slot_mem_in_valid), .wr_ready(wbm_64b_ar_slot_mem_in_ready), .wr_data(wbm_64b_ar),
        .rd_valid(wbm_64b_ar_slot_mem_valid), .rd_ready(wbm_64b_ar_slot_mem_ready), .rd_data(wbm_64b_ar_slot_mem),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for mem: round-robin, lock until handshake ----
    logic [5:0] mem_ar_arb_req;
    assign mem_ar_arb_req = {wbm_64b_ar_slot_mem_valid, p5m_64b_ar_slot_mem_valid, p4m_64b_ar_slot_mem_valid, l5m_64b_ar_slot_mem_valid, l4m_64b_ar_slot_mem_valid, cpu_64b_ar_slot_mem_valid};
    logic [2:0] mem_ar_arb_lock, mem_ar_arb_rr;
    logic mem_ar_arb_locked;
    wire [2:0] mem_ar_arb_pick = (mem_ar_arb_rr == 3'd0) ? (mem_ar_arb_req[0] ? 3'd0 : mem_ar_arb_req[1] ? 3'd1 : mem_ar_arb_req[2] ? 3'd2 : mem_ar_arb_req[3] ? 3'd3 : mem_ar_arb_req[4] ? 3'd4 : 3'd5) : 
        (mem_ar_arb_rr == 3'd1) ? (mem_ar_arb_req[1] ? 3'd1 : mem_ar_arb_req[2] ? 3'd2 : mem_ar_arb_req[3] ? 3'd3 : mem_ar_arb_req[4] ? 3'd4 : mem_ar_arb_req[5] ? 3'd5 : 3'd0) : 
        (mem_ar_arb_rr == 3'd2) ? (mem_ar_arb_req[2] ? 3'd2 : mem_ar_arb_req[3] ? 3'd3 : mem_ar_arb_req[4] ? 3'd4 : mem_ar_arb_req[5] ? 3'd5 : mem_ar_arb_req[0] ? 3'd0 : 3'd1) : 
        (mem_ar_arb_rr == 3'd3) ? (mem_ar_arb_req[3] ? 3'd3 : mem_ar_arb_req[4] ? 3'd4 : mem_ar_arb_req[5] ? 3'd5 : mem_ar_arb_req[0] ? 3'd0 : mem_ar_arb_req[1] ? 3'd1 : 3'd2) : 
        (mem_ar_arb_rr == 3'd4) ? (mem_ar_arb_req[4] ? 3'd4 : mem_ar_arb_req[5] ? 3'd5 : mem_ar_arb_req[0] ? 3'd0 : mem_ar_arb_req[1] ? 3'd1 : mem_ar_arb_req[2] ? 3'd2 : 3'd3) : 
        mem_ar_arb_req[5] ? 3'd5 : mem_ar_arb_req[0] ? 3'd0 : mem_ar_arb_req[1] ? 3'd1 : mem_ar_arb_req[2] ? 3'd2 : mem_ar_arb_req[3] ? 3'd3 : 3'd4;
    wire mem_ar_arb_gnt_valid = mem_ar_arb_locked || (|mem_ar_arb_req);
    wire [2:0] mem_ar_arb_gnt = mem_ar_arb_locked ? mem_ar_arb_lock : mem_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem_ar_arb_lock   <= '0;
            mem_ar_arb_rr     <= '0;
            mem_ar_arb_locked <= 1'b0;
        end else begin
            if (mem_axi_arvalid && mem_axi_arready) begin
                mem_ar_arb_locked <= 1'b0;
                mem_ar_arb_rr <= (mem_ar_arb_gnt == 3'd5) ? 3'd0 : mem_ar_arb_gnt + 1'b1;
            end else if (mem_axi_arvalid) begin
                mem_ar_arb_lock   <= mem_ar_arb_gnt;
                mem_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_ar_gnt_mem = mem_ar_arb_gnt_valid && (mem_ar_arb_gnt == 3'd0) && mem_ar_arb_req[0];
    wire l4m_64b_ar_gnt_mem = mem_ar_arb_gnt_valid && (mem_ar_arb_gnt == 3'd1) && mem_ar_arb_req[1];
    wire l5m_64b_ar_gnt_mem = mem_ar_arb_gnt_valid && (mem_ar_arb_gnt == 3'd2) && mem_ar_arb_req[2];
    wire p4m_64b_ar_gnt_mem = mem_ar_arb_gnt_valid && (mem_ar_arb_gnt == 3'd3) && mem_ar_arb_req[3];
    wire p5m_64b_ar_gnt_mem = mem_ar_arb_gnt_valid && (mem_ar_arb_gnt == 3'd4) && mem_ar_arb_req[4];
    wire wbm_64b_ar_gnt_mem = mem_ar_arb_gnt_valid && (mem_ar_arb_gnt == 3'd5) && mem_ar_arb_req[5];
    assign cpu_64b_ar_slot_mem_ready = cpu_64b_ar_gnt_mem && mem_axi_arready;
    assign l4m_64b_ar_slot_mem_ready = l4m_64b_ar_gnt_mem && mem_axi_arready;
    assign l5m_64b_ar_slot_mem_ready = l5m_64b_ar_gnt_mem && mem_axi_arready;
    assign p4m_64b_ar_slot_mem_ready = p4m_64b_ar_gnt_mem && mem_axi_arready;
    assign p5m_64b_ar_slot_mem_ready = p5m_64b_ar_gnt_mem && mem_axi_arready;
    assign wbm_64b_ar_slot_mem_ready = wbm_64b_ar_gnt_mem && mem_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign mem_axi_arid = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.id : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.id : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.id : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.id : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.id : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.id : '0);
    assign mem_axi_araddr = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.addr : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.addr : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.addr : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.addr : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.addr : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.addr : '0);
    assign mem_axi_arlen = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.len : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.len : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.len : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.len : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.len : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.len : '0);
    assign mem_axi_arsize = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.size : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.size : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.size : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.size : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.size : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.size : '0);
    assign mem_axi_arburst = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.burst : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.burst : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.burst : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.burst : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.burst : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.burst : '0);
    assign mem_axi_arlock = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.lock : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.lock : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.lock : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.lock : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.lock : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.lock : '0);
    assign mem_axi_arcache = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.cache : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.cache : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.cache : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.cache : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.cache : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.cache : '0);
    assign mem_axi_arprot = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.prot : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.prot : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.prot : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.prot : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.prot : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.prot : '0);
    assign mem_axi_arqos = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.qos : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.qos : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.qos : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.qos : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.qos : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.qos : '0);
    assign mem_axi_arregion = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.region : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.region : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.region : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.region : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.region : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.region : '0);
    assign mem_axi_aruser = (cpu_64b_ar_gnt_mem ? cpu_64b_ar_slot_mem.user : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_64b_ar_slot_mem.user : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_64b_ar_slot_mem.user : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_64b_ar_slot_mem.user : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_64b_ar_slot_mem.user : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_64b_ar_slot_mem.user : '0);
    assign mem_axi_arvalid = cpu_64b_ar_gnt_mem || l4m_64b_ar_gnt_mem || l5m_64b_ar_gnt_mem || p4m_64b_ar_gnt_mem || p5m_64b_ar_gnt_mem || wbm_64b_ar_gnt_mem;

    // Rready (slave -> the master whose response arbiter granted it)
    assign mem_axi_rready = (cpu_64b_r_rgnt_mem ? cpu_64b_rready : '0) |
        (l4m_64b_r_rgnt_mem ? l4m_64b_rready : '0) |
        (l5m_64b_r_rgnt_mem ? l5m_64b_rready : '0) |
        (p4m_64b_r_rgnt_mem ? p4m_64b_rready : '0) |
        (p5m_64b_r_rgnt_mem ? p5m_64b_rready : '0) |
        (wbm_64b_r_rgnt_mem ? wbm_64b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign mem_axi_bridge_id_ar = (cpu_64b_ar_gnt_mem ? cpu_bridge_id_ar : '0) |
        (l4m_64b_ar_gnt_mem ? l4m_bridge_id_ar : '0) |
        (l5m_64b_ar_gnt_mem ? l5m_bridge_id_ar : '0) |
        (p4m_64b_ar_gnt_mem ? p4m_bridge_id_ar : '0) |
        (p5m_64b_ar_gnt_mem ? p5m_bridge_id_ar : '0) |
        (wbm_64b_ar_gnt_mem ? wbm_bridge_id_ar : '0);


    // ================================================================
    // Slave 1: l4s (32b)
    // ================================================================
    // Multi-master (6 masters) → l4s
    //   - cpu (rw)
    //   - l4m (rw)
    //   - l5m (rw)
    //   - p4m (rw)
    //   - p5m (rw)
    //   - wbm (rw)

    wire cpu_32b_aw_to_l4s = ((cpu_32b_aw.addr >= 32'h10000000) && (cpu_32b_aw.addr <= 32'h10ffffff));
    wire cpu_32b_ar_to_l4s = ((cpu_32b_ar.addr >= 32'h10000000) && (cpu_32b_ar.addr <= 32'h10ffffff));
    wire l4m_32b_aw_to_l4s = ((l4m_32b_aw.addr >= 32'h10000000) && (l4m_32b_aw.addr <= 32'h10ffffff));
    wire l4m_32b_ar_to_l4s = ((l4m_32b_ar.addr >= 32'h10000000) && (l4m_32b_ar.addr <= 32'h10ffffff));
    wire l5m_32b_aw_to_l4s = ((l5m_32b_aw.addr >= 32'h10000000) && (l5m_32b_aw.addr <= 32'h10ffffff));
    wire l5m_32b_ar_to_l4s = ((l5m_32b_ar.addr >= 32'h10000000) && (l5m_32b_ar.addr <= 32'h10ffffff));
