    wire p4m_32b_ar_to_l4s = ((p4m_32b_ar.addr >= 32'h10000000) && (p4m_32b_ar.addr <= 32'h10ffffff));
    wire p5m_32b_aw_to_l4s = ((p5m_32b_aw.addr >= 32'h10000000) && (p5m_32b_aw.addr <= 32'h10ffffff));
    wire p5m_32b_ar_to_l4s = ((p5m_32b_ar.addr >= 32'h10000000) && (p5m_32b_ar.addr <= 32'h10ffffff));
    wire wbm_32b_aw_to_l4s = ((wbm_32b_aw.addr >= 32'h10000000) && (wbm_32b_aw.addr <= 32'h10ffffff));
    wire wbm_32b_ar_to_l4s = ((wbm_32b_ar.addr >= 32'h10000000) && (wbm_32b_ar.addr <= 32'h10ffffff));

    // AW request slots for l4s: arbitration at the slave pins
    assign cpu_32b_aw_slot_l4s_in_valid = cpu_32b_aw_to_l4s && cpu_32b_awvalid && !(cpu_32b_aw_hold_l4s || cpu_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_32b_aw_slot_l4s (
