        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_32b_aw_slot_l4s_in_valid = l4m_32b_aw_to_l4s && l4m_32b_awvalid && !(l4m_32b_aw_hold_l4s || l4m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l4m_32b_aw_slot_l4s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_32b_aw_slot_l4s_in_valid), .wr_ready(l4m_32b_aw_slot_l4s_in_ready), .wr_data(l4m_32b_aw),
        .rd_valid(l4m_32b_aw_slot_l4s_valid), .rd_ready(l4m_32b_aw_slot_l4s_ready), .rd_data(l4m_32b_aw_slot_l4s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
