    assign l5m_32b_aw_slot_l4s_in_valid = l5m_32b_aw_to_l4s && l5m_32b_awvalid && !(l5m_32b_aw_hold_l4s || l5m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l5m_32b_aw_slot_l4s (
