        .rd_valid(l5m_32b_aw_slot_l4s_valid), .rd_ready(l5m_32b_aw_slot_l4s_ready), .rd_data(l5m_32b_aw_slot_l4s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_32b_aw_slot_l4s_in_valid = p4m_32b_aw_to_l4s && p4m_32b_awvalid && !(p4m_32b_aw_hold_l4s || p4m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p4m_32b_aw_slot_l4s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_32b_aw_slot_l4s_in_valid), .wr_ready(p4m_32b_aw_slot_l4s_in_ready), .wr_data(p4m_32b_aw),
