        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_32b_aw_slot_l4s_in_valid = p5m_32b_aw_to_l4s && p5m_32b_awvalid && !(p5m_32b_aw_hold_l4s || p5m_32b_wdest_full);
