        .wr_valid(wbm_32b_aw_slot_l4s_in_valid), .wr_ready(wbm_32b_aw_slot_l4s_in_ready), .wr_data(wbm_32b_aw),
        .rd_valid(wbm_32b_aw_slot_l4s_valid), .rd_ready(wbm_32b_aw_slot_l4s_ready), .rd_data(wbm_32b_aw_slot_l4s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
