    // ---- AW arbiter for l4s: round-robin, lock until handshake ----
    logic [5:0] l4s_aw_arb_req;
    assign l4s_aw_arb_req = {wbm_32b_aw_slot_l4s_valid, p5m_32b_aw_slot_l4s_valid, p4m_32b_aw_slot_l4s_valid, l5m_32b_aw_slot_l4s_valid, l4m_32b_aw_slot_l4s_valid, cpu_32b_aw_slot_l4s_valid};
    logic [2:0] l4s_aw_arb_lock, l4s_aw_arb_rr;
    logic l4s_aw_arb_locked;
    wire [2:0] l4s_aw_arb_pick = (l4s_aw_arb_rr == 3'd0) ? (l4s_aw_arb_req[0] ? 3'd0 : l4s_aw_arb_req[1] ? 3'd1 : l4s_aw_arb_req[2] ? 3'd2 : l4s_aw_arb_req[3] ? 3'd3 : l4s_aw_arb_req[4] ? 3'd4 : 3'd5) : 
        (l4s_aw_arb_rr == 3'd1) ? (l4s_aw_arb_req[1] ? 3'd1 : l4s_aw_arb_req[2] ? 3'd2 : l4s_aw_arb_req[3] ? 3'd3 : l4s_aw_arb_req[4] ? 3'd4 : l4s_aw_arb_req[5] ? 3'd5 : 3'd0) : 
        (l4s_aw_arb_rr == 3'd2) ? (l4s_aw_arb_req[2] ? 3'd2 : l4s_aw_arb_req[3] ? 3'd3 : l4s_aw_arb_req[4] ? 3'd4 : l4s_aw_arb_req[5] ? 3'd5 : l4s_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (l4s_aw_arb_rr == 3'd3) ? (l4s_aw_arb_req[3] ? 3'd3 : l4s_aw_arb_req[4] ? 3'd4 : l4s_aw_arb_req[5] ? 3'd5 : l4s_aw_arb_req[0] ? 3'd0 : l4s_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        (l4s_aw_arb_rr == 3'd4) ? (l4s_aw_arb_req[4] ? 3'd4 : l4s_aw_arb_req[5] ? 3'd5 : l4s_aw_arb_req[0] ? 3'd0 : l4s_aw_arb_req[1] ? 3'd1 : l4s_aw_arb_req[2] ? 3'd2 : 3'd3) : 
        l4s_aw_arb_req[5] ? 3'd5 : l4s_aw_arb_req[0] ? 3'd0 : l4s_aw_arb_req[1] ? 3'd1 : l4s_aw_arb_req[2] ? 3'd2 : l4s_aw_arb_req[3] ? 3'd3 : 3'd4;
    wire l4s_aw_arb_gnt_valid = l4s_aw_arb_locked || (|l4s_aw_arb_req);
    wire [2:0] l4s_aw_arb_gnt = l4s_aw_arb_locked ? l4s_aw_arb_lock : l4s_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            l4s_aw_arb_lock   <= '0;
            l4s_aw_arb_rr     <= '0;
            l4s_aw_arb_locked <= 1'b0;
        end else begin
            if (l4s_axi_awvalid && l4s_axi_awready) begin
                l4s_aw_arb_locked <= 1'b0;
                l4s_aw_arb_rr <= (l4s_aw_arb_gnt == 3'd5) ? 3'd0 : l4s_aw_arb_gnt + 1'b1;
            end else if (l4s_axi_awvalid) begin
                l4s_aw_arb_lock   <= l4s_aw_arb_gnt;
                l4s_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_32b_aw_gnt_l4s = l4s_aw_arb_gnt_valid && (l4s_aw_arb_gnt == 3'd0) && l4s_aw_arb_req[0];
    wire l4m_32b_aw_gnt_l4s = l4s_aw_arb_gnt_valid && (l4s_aw_arb_gnt == 3'd1) && l4s_aw_arb_req[1];
    wire l5m_32b_aw_gnt_l4s = l4s_aw_arb_gnt_valid && (l4s_aw_arb_gnt == 3'd2) && l4s_aw_arb_req[2];
    wire p4m_32b_aw_gnt_l4s = l4s_aw_arb_gnt_valid && (l4s_aw_arb_gnt == 3'd3) && l4s_aw_arb_req[3];
    wire p5m_32b_aw_gnt_l4s = l4s_aw_arb_gnt_valid && (l4s_aw_arb_gnt == 3'd4) && l4s_aw_arb_req[4];
    wire wbm_32b_aw_gnt_l4s = l4s_aw_arb_gnt_valid && (l4s_aw_arb_gnt == 3'd5) && l4s_aw_arb_req[5];
    assign cpu_32b_aw_slot_l4s_ready = cpu_32b_aw_gnt_l4s && l4s_axi_awready;
    assign l4m_32b_aw_slot_l4s_ready = l4m_32b_aw_gnt_l4s && l4s_axi_awready;
    assign l5m_32b_aw_slot_l4s_ready = l5m_32b_aw_gnt_l4s && l4s_axi_awready;
    assign p4m_32b_aw_slot_l4s_ready = p4m_32b_aw_gnt_l4s && l4s_axi_awready;
    assign p5m_32b_aw_slot_l4s_ready = p5m_32b_aw_gnt_l4s && l4s_axi_awready;
    assign wbm_32b_aw_slot_l4s_ready = wbm_32b_aw_gnt_l4s && l4s_axi_awready;

