    assign l4s_axi_awid = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.id : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.id : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.id : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.id : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.id : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.id : '0);
    assign l4s_axi_awaddr = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.addr : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.addr : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.addr : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.addr : '0) |
