    assign l4s_axi_awsize = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.size : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.size : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.size : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.size : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.size : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.size : '0);
    assign l4s_axi_awburst = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.burst : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.burst : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.burst : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.burst : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.burst : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.burst : '0);
    assign l4s_axi_awlock = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.lock : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.lock : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.lock : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.lock : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.lock : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.lock : '0);
    assign l4s_axi_awcache = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.cache : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.cache : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.cache : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.cache : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.cache : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.cache : '0);
    assign l4s_axi_awprot = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.prot : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.prot : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.prot : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.prot : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.prot : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.prot : '0);
    assign l4s_axi_awqos = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.qos : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.qos : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.qos : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.qos : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.qos : '0) |
