    assign l4s_axi_awregion = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.region : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.region : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.region : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.region : '0) |
        (p5m_32b_aw_gnt_l4s ? p5m_32b_aw_slot_l4s.region : '0) |
        (wbm_32b_aw_gnt_l4s ? wbm_32b_aw_slot_l4s.region : '0);
    assign l4s_axi_awuser = (cpu_32b_aw_gnt_l4s ? cpu_32b_aw_slot_l4s.user : '0) |
        (l4m_32b_aw_gnt_l4s ? l4m_32b_aw_slot_l4s.user : '0) |
        (l5m_32b_aw_gnt_l4s ? l5m_32b_aw_slot_l4s.user : '0) |
        (p4m_32b_aw_gnt_l4s ? p4m_32b_aw_slot_l4s.user : '0) |
