    assign l4s_axi_awvalid = cpu_32b_aw_gnt_l4s || l4m_32b_aw_gnt_l4s || l5m_32b_aw_gnt_l4s || p4m_32b_aw_gnt_l4s || p5m_32b_aw_gnt_l4s || wbm_32b_aw_gnt_l4s;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] l4s_wowner_mem [16];
    logic [4:0] l4s_wowner_wptr, l4s_wowner_rptr;
    `ALWAYS_FF_RST(aclk, aresetn,
