            l4s_wowner_wptr <= '0;
            l4s_wowner_rptr <= '0;
        end else begin
            if (l4s_axi_awvalid && l4s_axi_awready) begin
                l4s_wowner_mem[l4s_wowner_wptr[3:0]] <= l4s_aw_arb_gnt;
                l4s_wowner_wptr <= l4s_wowner_wptr + 1'b1;
            end
            if (l4s_axi_wvalid && l4s_axi_wready && l4s_axi_wlast) begin
                l4s_wowner_rptr <= l4s_wowner_rptr + 1'b1;
            end
        end
    )
    wire l4s_wowner_valid = (l4s_wowner_wptr != l4s_wowner_rptr);
    wire [2:0] l4s_wowner_head = l4s_wowner_mem[l4s_wowner_rptr[3:0]];
    assign cpu_32b_w_sel_l4s = l4s_wowner_valid && (l4s_wowner_head == 3'd0) && cpu_32b_w_to_l4s;
    assign l4m_32b_w_sel_l4s = l4s_wowner_valid && (l4s_wowner_head == 3'd1) && l4m_32b_w_to_l4s;
    assign l5m_32b_w_sel_l4s = l4s_wowner_valid && (l4s_wowner_head == 3'd2) && l5m_32b_w_to_l4s;
    assign p4m_32b_w_sel_l4s = l4s_wowner_valid && (l4s_wowner_head == 3'd3) && p4m_32b_w_to_l4s;
    assign p5m_32b_w_sel_l4s = l4s_wowner_valid && (l4s_wowner_head == 3'd4) && p5m_32b_w_to_l4s;
    assign wbm_32b_w_sel_l4s = l4s_wowner_valid && (l4s_wowner_head == 3'd5) && wbm_32b_w_to_l4s;

