    assign l4s_axi_arvalid = cpu_32b_ar_gnt_l4s || l4m_32b_ar_gnt_l4s || l5m_32b_ar_gnt_l4s || p4m_32b_ar_gnt_l4s || p5m_32b_ar_gnt_l4s || wbm_32b_ar_gnt_l4s;

    // Rready (slave -> the master whose response arbiter granted it)
    assign l4s_axi_rready = (cpu_32b_r_rgnt_l4s ? cpu_32b_rready : '0) |
        (l4m_32b_r_rgnt_l4s ? l4m_32b_rready : '0) |
        (l5m_32b_r_rgnt_l4s ? l5m_32b_rready : '0) |
        (p4m_32b_r_rgnt_l4s ? p4m_32b_rready : '0) |
        (p5m_32b_r_rgnt_l4s ? p5m_32b_rready : '0) |
        (wbm_32b_r_rgnt_l4s ? wbm_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign l4s_axi_bridge_id_ar = (cpu_32b_ar_gnt_l4s ? cpu_bridge_id_ar : '0) |
        (l4m_32b_ar_gnt_l4s ? l4m_bridge_id_ar : '0) |
        (l5m_32b_ar_gnt_l4s ? l5m_bridge_id_ar : '0) |
        (p4m_32b_ar_gnt_l4s ? p4m_bridge_id_ar : '0) |
        (p5m_32b_ar_gnt_l4s ? p5m_bridge_id_ar : '0) |
        (wbm_32b_ar_gnt_l4s ? wbm_bridge_id_ar : '0);


    // ================================================================
    // Slave 2: l5s (64b)
    // ================================================================
    // Multi-master (6 masters) → l5s
    //   - cpu (rw)
    //   - l4m (rw)
    //   - l5m (rw)
    //   - p4m (rw)
    //   - p5m (rw)
    //   - wbm (rw)

    wire cpu_64b_aw_to_l5s = ((cpu_64b_aw.addr >= 32'h20000000) && (cpu_64b_aw.addr <= 32'h20ffffff));
    wire cpu_64b_ar_to_l5s = ((cpu_64b_ar.addr >= 32'h20000000) && (cpu_64b_ar.addr <= 32'h20ffffff));
    wire l4m_64b_aw_to_l5s = ((l4m_64b_aw.addr >= 32'h20000000) && (l4m_64b_aw.addr <= 32'h20ffffff));
    wire l4m_64b_ar_to_l5s = ((l4m_64b_ar.addr >= 32'h20000000) && (l4m_64b_ar.addr <= 32'h20ffffff));
    wire l5m_64b_aw_to_l5s = ((l5m_64b_aw.addr >= 32'h20000000) && (l5m_64b_aw.addr <= 32'h20ffffff));
    wire l5m_64b_ar_to_l5s = ((l5m_64b_ar.addr >= 32'h20000000) && (l5m_64b_ar.addr <= 32'h20ffffff));
    wire p4m_64b_aw_to_l5s = ((p4m_64b_aw.addr >= 32'h20000000) && (p4m_64b_aw.addr <= 32'h20ffffff));
    wire p4m_64b_ar_to_l5s = ((p4m_64b_ar.addr >= 32'h20000000) && (p4m_64b_ar.addr <= 32'h20ffffff));
    wire p5m_64b_aw_to_l5s = ((p5m_64b_aw.addr >= 32'h20000000) && (p5m_64b_aw.addr <= 32'h20ffffff));
    wire p5m_64b_ar_to_l5s = ((p5m_64b_ar.addr >= 32'h20000000) && (p5m_64b_ar.addr <= 32'h20ffffff));
    wire wbm_64b_aw_to_l5s = ((wbm_64b_aw.addr >= 32'h20000000) && (wbm_64b_aw.addr <= 32'h20ffffff));
    wire wbm_64b_ar_to_l5s = ((wbm_64b_ar.addr >= 32'h20000000) && (wbm_64b_ar.addr <= 32'h20ffffff));

    // AW request slots for l5s: arbitration at the slave pins
    assign cpu_64b_aw_slot_l5s_in_valid = cpu_64b_aw_to_l5s && cpu_64b_awvalid && !(cpu_64b_aw_hold_l5s || cpu_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_l5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_aw_slot_l5s_in_valid), .wr_ready(cpu_64b_aw_slot_l5s_in_ready), .wr_data(cpu_64b_aw),
        .rd_valid(cpu_64b_aw_slot_l5s_valid), .rd_ready(cpu_64b_aw_slot_l5s_ready), .rd_data(cpu_64b_aw_slot_l5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_64b_aw_slot_l5s_in_valid = l4m_64b_aw_to_l5s && l4m_64b_awvalid && !(l4m_64b_aw_hold_l5s || l4m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l4m_64b_aw_slot_l5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_64b_aw_slot_l5s_in_valid), .wr_ready(l4m_64b_aw_slot_l5s_in_ready), .wr_data(l4m_64b_aw),
        .rd_valid(l4m_64b_aw_slot_l5s_valid), .rd_ready(l4m_64b_aw_slot_l5s_ready), .rd_data(l4m_64b_aw_slot_l5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l5m_64b_aw_slot_l5s_in_valid = l5m_64b_aw_to_l5s && l5m_64b_awvalid && !(l5m_64b_aw_hold_l5s || l5m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l5m_64b_aw_slot_l5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l5m_64b_aw_slot_l5s_in_valid), .wr_ready(l5m_64b_aw_slot_l5s_in_ready), .wr_data(l5m_64b_aw),
        .rd_valid(l5m_64b_aw_slot_l5s_valid), .rd_ready(l5m_64b_aw_slot_l5s_ready), .rd_data(l5m_64b_aw_slot_l5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_64b_aw_slot_l5s_in_valid = p4m_64b_aw_to_l5s && p4m_64b_awvalid && !(p4m_64b_aw_hold_l5s || p4m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p4m_64b_aw_slot_l5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_64b_aw_slot_l5s_in_valid), .wr_ready(p4m_64b_aw_slot_l5s_in_ready), .wr_data(p4m_64b_aw),
        .rd_valid(p4m_64b_aw_slot_l5s_valid), .rd_ready(p4m_64b_aw_slot_l5s_ready), .rd_data(p4m_64b_aw_slot_l5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_64b_aw_slot_l5s_in_valid = p5m_64b_aw_to_l5s && p5m_64b_awvalid && !(p5m_64b_aw_hold_l5s || p5m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p5m_64b_aw_slot_l5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_64b_aw_slot_l5s_in_valid), .wr_ready(p5m_64b_aw_slot_l5s_in_ready), .wr_data(p5m_64b_aw),
        .rd_valid(p5m_64b_aw_slot_l5s_valid), .rd_ready(p5m_64b_aw_slot_l5s_ready), .rd_data(p5m_64b_aw_slot_l5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_64b_aw_slot_l5s_in_valid = wbm_64b_aw_to_l5s && wbm_64b_awvalid && !(wbm_64b_aw_hold_l5s || wbm_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_wbm_64b_aw_slot_l5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_64b_aw_slot_l5s_in_valid), .wr_ready(wbm_64b_aw_slot_l5s_in_ready), .wr_data(wbm_64b_aw),
        .rd_valid(wbm_64b_aw_slot_l5s_valid), .rd_ready(wbm_64b_aw_slot_l5s_ready), .rd_data(wbm_64b_aw_slot_l5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for l5s: round-robin, lock until handshake ----
    logic [5:0] l5s_aw_arb_req;
    assign l5s_aw_arb_req = {wbm_64b_aw_slot_l5s_valid, p5m_64b_aw_slot_l5s_valid, p4m_64b_aw_slot_l5s_valid, l5m_64b_aw_slot_l5s_valid, l4m_64b_aw_slot_l5s_valid, cpu_64b_aw_slot_l5s_valid};
    logic [2:0] l5s_aw_arb_lock, l5s_aw_arb_rr;
    logic l5s_aw_arb_locked;
    wire [2:0] l5s_aw_arb_pick = (l5s_aw_arb_rr == 3'd0) ? (l5s_aw_arb_req[0] ? 3'd0 : l5s_aw_arb_req[1] ? 3'd1 : l5s_aw_arb_req[2] ? 3'd2 : l5s_aw_arb_req[3] ? 3'd3 : l5s_aw_arb_req[4] ? 3'd4 : 3'd5) : 
        (l5s_aw_arb_rr == 3'd1) ? (l5s_aw_arb_req[1] ? 3'd1 : l5s_aw_arb_req[2] ? 3'd2 : l5s_aw_arb_req[3] ? 3'd3 : l5s_aw_arb_req[4] ? 3'd4 : l5s_aw_arb_req[5] ? 3'd5 : 3'd0) : 
        (l5s_aw_arb_rr == 3'd2) ? (l5s_aw_arb_req[2] ? 3'd2 : l5s_aw_arb_req[3] ? 3'd3 : l5s_aw_arb_req[4] ? 3'd4 : l5s_aw_arb_req[5] ? 3'd5 : l5s_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (l5s_aw_arb_rr == 3'd3) ? (l5s_aw_arb_req[3] ? 3'd3 : l5s_aw_arb_req[4] ? 3'd4 : l5s_aw_arb_req[5] ? 3'd5 : l5s_aw_arb_req[0] ? 3'd0 : l5s_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        (l5s_aw_arb_rr == 3'd4) ? (l5s_aw_arb_req[4] ? 3'd4 : l5s_aw_arb_req[5] ? 3'd5 : l5s_aw_arb_req[0] ? 3'd0 : l5s_aw_arb_req[1] ? 3'd1 : l5s_aw_arb_req[2] ? 3'd2 : 3'd3) : 
        l5s_aw_arb_req[5] ? 3'd5 : l5s_aw_arb_req[0] ? 3'd0 : l5s_aw_arb_req[1] ? 3'd1 : l5s_aw_arb_req[2] ? 3'd2 : l5s_aw_arb_req[3] ? 3'd3 : 3'd4;
    wire l5s_aw_arb_gnt_valid = l5s_aw_arb_locked || (|l5s_aw_arb_req);
    wire [2:0] l5s_aw_arb_gnt = l5s_aw_arb_locked ? l5s_aw_arb_lock : l5s_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            l5s_aw_arb_lock   <= '0;
            l5s_aw_arb_rr     <= '0;
            l5s_aw_arb_locked <= 1'b0;
        end else begin
            if (l5s_axi_awvalid && l5s_axi_awready) begin
                l5s_aw_arb_locked <= 1'b0;
                l5s_aw_arb_rr <= (l5s_aw_arb_gnt == 3'd5) ? 3'd0 : l5s_aw_arb_gnt + 1'b1;
            end else if (l5s_axi_awvalid) begin
                l5s_aw_arb_lock   <= l5s_aw_arb_gnt;
                l5s_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_aw_gnt_l5s = l5s_aw_arb_gnt_valid && (l5s_aw_arb_gnt == 3'd0) && l5s_aw_arb_req[0];
    wire l4m_64b_aw_gnt_l5s = l5s_aw_arb_gnt_valid && (l5s_aw_arb_gnt == 3'd1) && l5s_aw_arb_req[1];
    wire l5m_64b_aw_gnt_l5s = l5s_aw_arb_gnt_valid && (l5s_aw_arb_gnt == 3'd2) && l5s_aw_arb_req[2];
    wire p4m_64b_aw_gnt_l5s = l5s_aw_arb_gnt_valid && (l5s_aw_arb_gnt == 3'd3) && l5s_aw_arb_req[3];
    wire p5m_64b_aw_gnt_l5s = l5s_aw_arb_gnt_valid && (l5s_aw_arb_gnt == 3'd4) && l5s_aw_arb_req[4];
    wire wbm_64b_aw_gnt_l5s = l5s_aw_arb_gnt_valid && (l5s_aw_arb_gnt == 3'd5) && l5s_aw_arb_req[5];
    assign cpu_64b_aw_slot_l5s_ready = cpu_64b_aw_gnt_l5s && l5s_axi_awready;
    assign l4m_64b_aw_slot_l5s_ready = l4m_64b_aw_gnt_l5s && l5s_axi_awready;
    assign l5m_64b_aw_slot_l5s_ready = l5m_64b_aw_gnt_l5s && l5s_axi_awready;
    assign p4m_64b_aw_slot_l5s_ready = p4m_64b_aw_gnt_l5s && l5s_axi_awready;
    assign p5m_64b_aw_slot_l5s_ready = p5m_64b_aw_gnt_l5s && l5s_axi_awready;
    assign wbm_64b_aw_slot_l5s_ready = wbm_64b_aw_gnt_l5s && l5s_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign l5s_axi_awid = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.id : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.id : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.id : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.id : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.id : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.id : '0);
    assign l5s_axi_awaddr = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.addr : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.addr : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.addr : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.addr : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.addr : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.addr : '0);
    assign l5s_axi_awlen = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.len : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.len : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.len : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.len : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.len : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.len : '0);
    assign l5s_axi_awsize = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.size : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.size : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.size : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.size : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.size : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.size : '0);
    assign l5s_axi_awburst = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.burst : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.burst : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.burst : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.burst : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.burst : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.burst : '0);
    assign l5s_axi_awlock = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.lock : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.lock : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.lock : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.lock : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.lock : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.lock : '0);
    assign l5s_axi_awcache = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.cache : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.cache : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.cache : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.cache : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.cache : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.cache : '0);
    assign l5s_axi_awprot = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.prot : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.prot : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.prot : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.prot : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.prot : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.prot : '0);
    assign l5s_axi_awqos = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.qos : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.qos : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.qos : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.qos : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.qos : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.qos : '0);
    assign l5s_axi_awregion = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.region : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.region : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.region : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.region : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.region : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.region : '0);
    assign l5s_axi_awuser = (cpu_64b_aw_gnt_l5s ? cpu_64b_aw_slot_l5s.user : '0) |
        (l4m_64b_aw_gnt_l5s ? l4m_64b_aw_slot_l5s.user : '0) |
        (l5m_64b_aw_gnt_l5s ? l5m_64b_aw_slot_l5s.user : '0) |
        (p4m_64b_aw_gnt_l5s ? p4m_64b_aw_slot_l5s.user : '0) |
        (p5m_64b_aw_gnt_l5s ? p5m_64b_aw_slot_l5s.user : '0) |
        (wbm_64b_aw_gnt_l5s ? wbm_64b_aw_slot_l5s.user : '0);
    assign l5s_axi_awvalid = cpu_64b_aw_gnt_l5s || l4m_64b_aw_gnt_l5s || l5m_64b_aw_gnt_l5s || p4m_64b_aw_gnt_l5s || p5m_64b_aw_gnt_l5s || wbm_64b_aw_gnt_l5s;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] l5s_wowner_mem [16];
