        end
    )
    wire cpu_32b_ar_gnt_p4s = p4s_ar_arb_gnt_valid && (p4s_ar_arb_gnt == 3'd0) && p4s_ar_arb_req[0];
    wire l4m_32b_ar_gnt_p4s = p4s_ar_arb_gnt_valid && (p4s_ar_arb_gnt == 3'd1) && p4s_ar_arb_req[1];
    wire l5m_32b_ar_gnt_p4s = p4s_ar_arb_gnt_valid && (p4s_ar_arb_gnt == 3'd2) && p4s_ar_arb_req[2];
    wire p4m_32b_ar_gnt_p4s = p4s_ar_arb_gnt_valid && (p4s_ar_arb_gnt == 3'd3) && p4s_ar_arb_req[3];
    wire p5m_32b_ar_gnt_p4s = p4s_ar_arb_gnt_valid && (p4s_ar_arb_gnt == 3'd4) && p4s_ar_arb_req[4];
    wire wbm_32b_ar_gnt_p4s = p4s_ar_arb_gnt_valid && (p4s_ar_arb_gnt == 3'd5) && p4s_ar_arb_req[5];
    assign cpu_32b_ar_slot_p4s_ready = cpu_32b_ar_gnt_p4s && p4s_axi_arready;
    assign l4m_32b_ar_slot_p4s_ready = l4m_32b_ar_gnt_p4s && p4s_axi_arready;
    assign l5m_32b_ar_slot_p4s_ready = l5m_32b_ar_gnt_p4s && p4s_axi_arready;
    assign p4m_32b_ar_slot_p4s_ready = p4m_32b_ar_gnt_p4s && p4s_axi_arready;
    assign p5m_32b_ar_slot_p4s_ready = p5m_32b_ar_gnt_p4s && p4s_axi_arready;
    assign wbm_32b_ar_slot_p4s_ready = wbm_32b_ar_gnt_p4s && p4s_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign p4s_axi_arid = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.id : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.id : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.id : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.id : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.id : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.id : '0);
    assign p4s_axi_araddr = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.addr : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.addr : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.addr : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.addr : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.addr : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.addr : '0);
    assign p4s_axi_arlen = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.len : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.len : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.len : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.len : '0) |
