        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.len : '0);
    assign p4s_axi_arsize = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.size : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.size : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.size : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.size : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.size : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.size : '0);
    assign p4s_axi_arburst = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.burst : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.burst : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.burst : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.burst : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.burst : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.burst : '0);
    assign p4s_axi_arlock = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.lock : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.lock : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.lock : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.lock : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.lock : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.lock : '0);
    assign p4s_axi_arcache = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.cache : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.cache : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.cache : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.cache : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.cache : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.cache : '0);
    assign p4s_axi_arprot = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.prot : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.prot : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.prot : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.prot : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.prot : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.prot : '0);
    assign p4s_axi_arqos = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.qos : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.qos : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.qos : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.qos : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.qos : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.qos : '0);
    assign p4s_axi_arregion = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.region : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.region : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.region : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.region : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.region : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.region : '0);
    assign p4s_axi_aruser = (cpu_32b_ar_gnt_p4s ? cpu_32b_ar_slot_p4s.user : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_32b_ar_slot_p4s.user : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_32b_ar_slot_p4s.user : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_32b_ar_slot_p4s.user : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_32b_ar_slot_p4s.user : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_32b_ar_slot_p4s.user : '0);
    assign p4s_axi_arvalid = cpu_32b_ar_gnt_p4s || l4m_32b_ar_gnt_p4s || l5m_32b_ar_gnt_p4s || p4m_32b_ar_gnt_p4s || p5m_32b_ar_gnt_p4s || wbm_32b_ar_gnt_p4s;

    // Rready (slave -> the master whose response arbiter granted it)
    assign p4s_axi_rready = (cpu_32b_r_rgnt_p4s ? cpu_32b_rready : '0) |
        (l4m_32b_r_rgnt_p4s ? l4m_32b_rready : '0) |
        (l5m_32b_r_rgnt_p4s ? l5m_32b_rready : '0) |
        (p4m_32b_r_rgnt_p4s ? p4m_32b_rready : '0) |
        (p5m_32b_r_rgnt_p4s ? p5m_32b_rready : '0) |
        (wbm_32b_r_rgnt_p4s ? wbm_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign p4s_axi_bridge_id_ar = (cpu_32b_ar_gnt_p4s ? cpu_bridge_id_ar : '0) |
        (l4m_32b_ar_gnt_p4s ? l4m_bridge_id_ar : '0) |
        (l5m_32b_ar_gnt_p4s ? l5m_bridge_id_ar : '0) |
        (p4m_32b_ar_gnt_p4s ? p4m_bridge_id_ar : '0) |
        (p5m_32b_ar_gnt_p4s ? p5m_bridge_id_ar : '0) |
        (wbm_32b_ar_gnt_p4s ? wbm_bridge_id_ar : '0);


    // ================================================================
    // Slave 4: p5s (32b)
    // ================================================================
    // Multi-master (6 masters) → p5s
    //   - cpu (rw)
    //   - l4m (rw)
    //   - l5m (rw)
    //   - p4m (rw)
    //   - p5m (rw)
    //   - wbm (rw)

    wire cpu_32b_aw_to_p5s = ((cpu_32b_aw.addr >= 32'h40000000) && (cpu_32b_aw.addr <= 32'h400fffff));
    wire cpu_32b_ar_to_p5s = ((cpu_32b_ar.addr >= 32'h40000000) && (cpu_32b_ar.addr <= 32'h400fffff));
    wire l4m_32b_aw_to_p5s = ((l4m_32b_aw.addr >= 32'h40000000) && (l4m_32b_aw.addr <= 32'h400fffff));
    wire l4m_32b_ar_to_p5s = ((l4m_32b_ar.addr >= 32'h40000000) && (l4m_32b_ar.addr <= 32'h400fffff));
    wire l5m_32b_aw_to_p5s = ((l5m_32b_aw.addr >= 32'h40000000) && (l5m_32b_aw.addr <= 32'h400fffff));
    wire l5m_32b_ar_to_p5s = ((l5m_32b_ar.addr >= 32'h40000000) && (l5m_32b_ar.addr <= 32'h400fffff));
    wire p4m_32b_aw_to_p5s = ((p4m_32b_aw.addr >= 32'h40000000) && (p4m_32b_aw.addr <= 32'h400fffff));
    wire p4m_32b_ar_to_p5s = ((p4m_32b_ar.addr >= 32'h40000000) && (p4m_32b_ar.addr <= 32'h400fffff));
    wire p5m_32b_aw_to_p5s = ((p5m_32b_aw.addr >= 32'h40000000) && (p5m_32b_aw.addr <= 32'h400fffff));
    wire p5m_32b_ar_to_p5s = ((p5m_32b_ar.addr >= 32'h40000000) && (p5m_32b_ar.addr <= 32'h400fffff));
    wire wbm_32b_aw_to_p5s = ((wbm_32b_aw.addr >= 32'h40000000) && (wbm_32b_aw.addr <= 32'h400fffff));
    wire wbm_32b_ar_to_p5s = ((wbm_32b_ar.addr >= 32'h40000000) && (wbm_32b_ar.addr <= 32'h400fffff));

    // AW request slots for p5s: arbitration at the slave pins
    assign cpu_32b_aw_slot_p5s_in_valid = cpu_32b_aw_to_p5s && cpu_32b_awvalid && !(cpu_32b_aw_hold_p5s || cpu_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_32b_aw_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_aw_slot_p5s_in_valid), .wr_ready(cpu_32b_aw_slot_p5s_in_ready), .wr_data(cpu_32b_aw),
        .rd_valid(cpu_32b_aw_slot_p5s_valid), .rd_ready(cpu_32b_aw_slot_p5s_ready), .rd_data(cpu_32b_aw_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_32b_aw_slot_p5s_in_valid = l4m_32b_aw_to_p5s && l4m_32b_awvalid && !(l4m_32b_aw_hold_p5s || l4m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l4m_32b_aw_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_32b_aw_slot_p5s_in_valid), .wr_ready(l4m_32b_aw_slot_p5s_in_ready), .wr_data(l4m_32b_aw),
        .rd_valid(l4m_32b_aw_slot_p5s_valid), .rd_ready(l4m_32b_aw_slot_p5s_ready), .rd_data(l4m_32b_aw_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l5m_32b_aw_slot_p5s_in_valid = l5m_32b_aw_to_p5s && l5m_32b_awvalid && !(l5m_32b_aw_hold_p5s || l5m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l5m_32b_aw_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l5m_32b_aw_slot_p5s_in_valid), .wr_ready(l5m_32b_aw_slot_p5s_in_ready), .wr_data(l5m_32b_aw),
        .rd_valid(l5m_32b_aw_slot_p5s_valid), .rd_ready(l5m_32b_aw_slot_p5s_ready), .rd_data(l5m_32b_aw_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_32b_aw_slot_p5s_in_valid = p4m_32b_aw_to_p5s && p4m_32b_awvalid && !(p4m_32b_aw_hold_p5s || p4m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p4m_32b_aw_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_32b_aw_slot_p5s_in_valid), .wr_ready(p4m_32b_aw_slot_p5s_in_ready), .wr_data(p4m_32b_aw),
        .rd_valid(p4m_32b_aw_slot_p5s_valid), .rd_ready(p4m_32b_aw_slot_p5s_ready), .rd_data(p4m_32b_aw_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_32b_aw_slot_p5s_in_valid = p5m_32b_aw_to_p5s && p5m_32b_awvalid && !(p5m_32b_aw_hold_p5s || p5m_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p5m_32b_aw_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_32b_aw_slot_p5s_in_valid), .wr_ready(p5m_32b_aw_slot_p5s_in_ready), .wr_data(p5m_32b_aw),
        .rd_valid(p5m_32b_aw_slot_p5s_valid), .rd_ready(p5m_32b_aw_slot_p5s_ready), .rd_data(p5m_32b_aw_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_32b_aw_slot_p5s_in_valid = wbm_32b_aw_to_p5s && wbm_32b_awvalid && !(wbm_32b_aw_hold_p5s || wbm_32b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_wbm_32b_aw_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_32b_aw_slot_p5s_in_valid), .wr_ready(wbm_32b_aw_slot_p5s_in_ready), .wr_data(wbm_32b_aw),
        .rd_valid(wbm_32b_aw_slot_p5s_valid), .rd_ready(wbm_32b_aw_slot_p5s_ready), .rd_data(wbm_32b_aw_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for p5s: round-robin, lock until handshake ----
    logic [5:0] p5s_aw_arb_req;
    assign p5s_aw_arb_req = {wbm_32b_aw_slot_p5s_valid, p5m_32b_aw_slot_p5s_valid, p4m_32b_aw_slot_p5s_valid, l5m_32b_aw_slot_p5s_valid, l4m_32b_aw_slot_p5s_valid, cpu_32b_aw_slot_p5s_valid};
    logic [2:0] p5s_aw_arb_lock, p5s_aw_arb_rr;
    logic p5s_aw_arb_locked;
    wire [2:0] p5s_aw_arb_pick = (p5s_aw_arb_rr == 3'd0) ? (p5s_aw_arb_req[0] ? 3'd0 : p5s_aw_arb_req[1] ? 3'd1 : p5s_aw_arb_req[2] ? 3'd2 : p5s_aw_arb_req[3] ? 3'd3 : p5s_aw_arb_req[4] ? 3'd4 : 3'd5) : 
        (p5s_aw_arb_rr == 3'd1) ? (p5s_aw_arb_req[1] ? 3'd1 : p5s_aw_arb_req[2] ? 3'd2 : p5s_aw_arb_req[3] ? 3'd3 : p5s_aw_arb_req[4] ? 3'd4 : p5s_aw_arb_req[5] ? 3'd5 : 3'd0) : 
        (p5s_aw_arb_rr == 3'd2) ? (p5s_aw_arb_req[2] ? 3'd2 : p5s_aw_arb_req[3] ? 3'd3 : p5s_aw_arb_req[4] ? 3'd4 : p5s_aw_arb_req[5] ? 3'd5 : p5s_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (p5s_aw_arb_rr == 3'd3) ? (p5s_aw_arb_req[3] ? 3'd3 : p5s_aw_arb_req[4] ? 3'd4 : p5s_aw_arb_req[5] ? 3'd5 : p5s_aw_arb_req[0] ? 3'd0 : p5s_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        (p5s_aw_arb_rr == 3'd4) ? (p5s_aw_arb_req[4] ? 3'd4 : p5s_aw_arb_req[5] ? 3'd5 : p5s_aw_arb_req[0] ? 3'd0 : p5s_aw_arb_req[1] ? 3'd1 : p5s_aw_arb_req[2] ? 3'd2 : 3'd3) : 
        p5s_aw_arb_req[5] ? 3'd5 : p5s_aw_arb_req[0] ? 3'd0 : p5s_aw_arb_req[1] ? 3'd1 : p5s_aw_arb_req[2] ? 3'd2 : p5s_aw_arb_req[3] ? 3'd3 : 3'd4;
    wire p5s_aw_arb_gnt_valid = p5s_aw_arb_locked || (|p5s_aw_arb_req);
    wire [2:0] p5s_aw_arb_gnt = p5s_aw_arb_locked ? p5s_aw_arb_lock : p5s_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            p5s_aw_arb_lock   <= '0;
            p5s_aw_arb_rr     <= '0;
            p5s_aw_arb_locked <= 1'b0;
        end else begin
            if (p5s_axi_awvalid && p5s_axi_awready) begin
                p5s_aw_arb_locked <= 1'b0;
                p5s_aw_arb_rr <= (p5s_aw_arb_gnt == 3'd5) ? 3'd0 : p5s_aw_arb_gnt + 1'b1;
            end else if (p5s_axi_awvalid) begin
                p5s_aw_arb_lock   <= p5s_aw_arb_gnt;
                p5s_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_32b_aw_gnt_p5s = p5s_aw_arb_gnt_valid && (p5s_aw_arb_gnt == 3'd0) && p5s_aw_arb_req[0];
    wire l4m_32b_aw_gnt_p5s = p5s_aw_arb_gnt_valid && (p5s_aw_arb_gnt == 3'd1) && p5s_aw_arb_req[1];
    wire l5m_32b_aw_gnt_p5s = p5s_aw_arb_gnt_valid && (p5s_aw_arb_gnt == 3'd2) && p5s_aw_arb_req[2];
    wire p4m_32b_aw_gnt_p5s = p5s_aw_arb_gnt_valid && (p5s_aw_arb_gnt == 3'd3) && p5s_aw_arb_req[3];
    wire p5m_32b_aw_gnt_p5s = p5s_aw_arb_gnt_valid && (p5s_aw_arb_gnt == 3'd4) && p5s_aw_arb_req[4];
    wire wbm_32b_aw_gnt_p5s = p5s_aw_arb_gnt_valid && (p5s_aw_arb_gnt == 3'd5) && p5s_aw_arb_req[5];
    assign cpu_32b_aw_slot_p5s_ready = cpu_32b_aw_gnt_p5s && p5s_axi_awready;
    assign l4m_32b_aw_slot_p5s_ready = l4m_32b_aw_gnt_p5s && p5s_axi_awready;
    assign l5m_32b_aw_slot_p5s_ready = l5m_32b_aw_gnt_p5s && p5s_axi_awready;
    assign p4m_32b_aw_slot_p5s_ready = p4m_32b_aw_gnt_p5s && p5s_axi_awready;
    assign p5m_32b_aw_slot_p5s_ready = p5m_32b_aw_gnt_p5s && p5s_axi_awready;
    assign wbm_32b_aw_slot_p5s_ready = wbm_32b_aw_gnt_p5s && p5s_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign p5s_axi_awid = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.id : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.id : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.id : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.id : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.id : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.id : '0);
    assign p5s_axi_awaddr = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.addr : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.addr : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.addr : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.addr : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.addr : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.addr : '0);
    assign p5s_axi_awlen = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.len : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.len : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.len : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.len : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.len : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.len : '0);
    assign p5s_axi_awsize = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.size : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.size : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.size : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.size : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.size : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.size : '0);
    assign p5s_axi_awburst = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.burst : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.burst : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.burst : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.burst : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.burst : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.burst : '0);
    assign p5s_axi_awlock = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.lock : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.lock : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.lock : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.lock : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.lock : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.lock : '0);
    assign p5s_axi_awcache = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.cache : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.cache : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.cache : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.cache : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.cache : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.cache : '0);
    assign p5s_axi_awprot = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.prot : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.prot : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.prot : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.prot : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.prot : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.prot : '0);
    assign p5s_axi_awqos = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.qos : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.qos : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.qos : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.qos : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.qos : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.qos : '0);
    assign p5s_axi_awregion = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.region : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.region : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.region : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.region : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.region : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.region : '0);
    assign p5s_axi_awuser = (cpu_32b_aw_gnt_p5s ? cpu_32b_aw_slot_p5s.user : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_32b_aw_slot_p5s.user : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_32b_aw_slot_p5s.user : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_32b_aw_slot_p5s.user : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_32b_aw_slot_p5s.user : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_32b_aw_slot_p5s.user : '0);
    assign p5s_axi_awvalid = cpu_32b_aw_gnt_p5s || l4m_32b_aw_gnt_p5s || l5m_32b_aw_gnt_p5s || p4m_32b_aw_gnt_p5s || p5m_32b_aw_gnt_p5s || wbm_32b_aw_gnt_p5s;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] p5s_wowner_mem [16];
    logic [4:0] p5s_wowner_wptr, p5s_wowner_rptr;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            p5s_wowner_wptr <= '0;
            p5s_wowner_rptr <= '0;
        end else begin
            if (p5s_axi_awvalid && p5s_axi_awready) begin
                p5s_wowner_mem[p5s_wowner_wptr[3:0]] <= p5s_aw_arb_gnt;
                p5s_wowner_wptr <= p5s_wowner_wptr + 1'b1;
            end
            if (p5s_axi_wvalid && p5s_axi_wready && p5s_axi_wlast) begin
                p5s_wowner_rptr <= p5s_wowner_rptr + 1'b1;
            end
        end
    )
    wire p5s_wowner_valid = (p5s_wowner_wptr != p5s_wowner_rptr);
    wire [2:0] p5s_wowner_head = p5s_wowner_mem[p5s_wowner_rptr[3:0]];
    assign cpu_32b_w_sel_p5s = p5s_wowner_valid && (p5s_wowner_head == 3'd0) && cpu_32b_w_to_p5s;
    assign l4m_32b_w_sel_p5s = p5s_wowner_valid && (p5s_wowner_head == 3'd1) && l4m_32b_w_to_p5s;
    assign l5m_32b_w_sel_p5s = p5s_wowner_valid && (p5s_wowner_head == 3'd2) && l5m_32b_w_to_p5s;
    assign p4m_32b_w_sel_p5s = p5s_wowner_valid && (p5s_wowner_head == 3'd3) && p4m_32b_w_to_p5s;
    assign p5m_32b_w_sel_p5s = p5s_wowner_valid && (p5s_wowner_head == 3'd4) && p5m_32b_w_to_p5s;
    assign wbm_32b_w_sel_p5s = p5s_wowner_valid && (p5s_wowner_head == 3'd5) && wbm_32b_w_to_p5s;

    // W channel (owner-gated mux across writing masters)
    assign p5s_axi_wdata = ((cpu_32b_w_sel_p5s && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((l4m_32b_w_sel_p5s && l4m_32b_wvalid) ? l4m_32b_w.data : '0) |
        ((l5m_32b_w_sel_p5s && l5m_32b_wvalid) ? l5m_32b_w.data : '0) |
        ((p4m_32b_w_sel_p5s && p4m_32b_wvalid) ? p4m_32b_w.data : '0) |
        ((p5m_32b_w_sel_p5s && p5m_32b_wvalid) ? p5m_32b_w.data : '0) |
        ((wbm_32b_w_sel_p5s && wbm_32b_wvalid) ? wbm_32b_w.data : '0);
    assign p5s_axi_wstrb = ((cpu_32b_w_sel_p5s && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((l4m_32b_w_sel_p5s && l4m_32b_wvalid) ? l4m_32b_w.strb : '0) |
        ((l5m_32b_w_sel_p5s && l5m_32b_wvalid) ? l5m_32b_w.strb : '0) |
        ((p4m_32b_w_sel_p5s && p4m_32b_wvalid) ? p4m_32b_w.strb : '0) |
        ((p5m_32b_w_sel_p5s && p5m_32b_wvalid) ? p5m_32b_w.strb : '0) |
        ((wbm_32b_w_sel_p5s && wbm_32b_wvalid) ? wbm_32b_w.strb : '0);
    assign p5s_axi_wlast = ((cpu_32b_w_sel_p5s && cpu_32b_wvalid) ? cpu_32b_w.last : '0) |
        ((l4m_32b_w_sel_p5s && l4m_32b_wvalid) ? l4m_32b_w.last : '0) |
        ((l5m_32b_w_sel_p5s && l5m_32b_wvalid) ? l5m_32b_w.last : '0) |
        ((p4m_32b_w_sel_p5s && p4m_32b_wvalid) ? p4m_32b_w.last : '0) |
        ((p5m_32b_w_sel_p5s && p5m_32b_wvalid) ? p5m_32b_w.last : '0) |
        ((wbm_32b_w_sel_p5s && wbm_32b_wvalid) ? wbm_32b_w.last : '0);
    assign p5s_axi_wuser = ((cpu_32b_w_sel_p5s && cpu_32b_wvalid) ? cpu_32b_w.user : '0) |
        ((l4m_32b_w_sel_p5s && l4m_32b_wvalid) ? l4m_32b_w.user : '0) |
        ((l5m_32b_w_sel_p5s && l5m_32b_wvalid) ? l5m_32b_w.user : '0) |
        ((p4m_32b_w_sel_p5s && p4m_32b_wvalid) ? p4m_32b_w.user : '0) |
        ((p5m_32b_w_sel_p5s && p5m_32b_wvalid) ? p5m_32b_w.user : '0) |
        ((wbm_32b_w_sel_p5s && wbm_32b_wvalid) ? wbm_32b_w.user : '0);
    assign p5s_axi_wvalid = (cpu_32b_w_sel_p5s && cpu_32b_wvalid) || (l4m_32b_w_sel_p5s && l4m_32b_wvalid) || (l5m_32b_w_sel_p5s && l5m_32b_wvalid) || (p4m_32b_w_sel_p5s && p4m_32b_wvalid) || (p5m_32b_w_sel_p5s && p5m_32b_wvalid) || (wbm_32b_w_sel_p5s && wbm_32b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign p5s_axi_bready = (cpu_32b_b_rgnt_p5s ? cpu_32b_bready : '0) |
        (l4m_32b_b_rgnt_p5s ? l4m_32b_bready : '0) |
        (l5m_32b_b_rgnt_p5s ? l5m_32b_bready : '0) |
        (p4m_32b_b_rgnt_p5s ? p4m_32b_bready : '0) |
        (p5m_32b_b_rgnt_p5s ? p5m_32b_bready : '0) |
        (wbm_32b_b_rgnt_p5s ? wbm_32b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign p5s_axi_bridge_id_aw = (cpu_32b_aw_gnt_p5s ? cpu_bridge_id_aw : '0) |
        (l4m_32b_aw_gnt_p5s ? l4m_bridge_id_aw : '0) |
        (l5m_32b_aw_gnt_p5s ? l5m_bridge_id_aw : '0) |
        (p4m_32b_aw_gnt_p5s ? p4m_bridge_id_aw : '0) |
        (p5m_32b_aw_gnt_p5s ? p5m_bridge_id_aw : '0) |
        (wbm_32b_aw_gnt_p5s ? wbm_bridge_id_aw : '0);

    // AR request slots for p5s: arbitration at the slave pins
    assign cpu_32b_ar_slot_p5s_in_valid = cpu_32b_ar_to_p5s && cpu_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_32b_ar_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_ar_slot_p5s_in_valid), .wr_ready(cpu_32b_ar_slot_p5s_in_ready), .wr_data(cpu_32b_ar),
        .rd_valid(cpu_32b_ar_slot_p5s_valid), .rd_ready(cpu_32b_ar_slot_p5s_ready), .rd_data(cpu_32b_ar_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_32b_ar_slot_p5s_in_valid = l4m_32b_ar_to_p5s && l4m_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_l4m_32b_ar_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_32b_ar_slot_p5s_in_valid), .wr_ready(l4m_32b_ar_slot_p5s_in_ready), .wr_data(l4m_32b_ar),
        .rd_valid(l4m_32b_ar_slot_p5s_valid), .rd_ready(l4m_32b_ar_slot_p5s_ready), .rd_data(l4m_32b_ar_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l5m_32b_ar_slot_p5s_in_valid = l5m_32b_ar_to_p5s && l5m_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_l5m_32b_ar_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l5m_32b_ar_slot_p5s_in_valid), .wr_ready(l5m_32b_ar_slot_p5s_in_ready), .wr_data(l5m_32b_ar),
        .rd_valid(l5m_32b_ar_slot_p5s_valid), .rd_ready(l5m_32b_ar_slot_p5s_ready), .rd_data(l5m_32b_ar_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_32b_ar_slot_p5s_in_valid = p4m_32b_ar_to_p5s && p4m_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_p4m_32b_ar_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_32b_ar_slot_p5s_in_valid), .wr_ready(p4m_32b_ar_slot_p5s_in_ready), .wr_data(p4m_32b_ar),
        .rd_valid(p4m_32b_ar_slot_p5s_valid), .rd_ready(p4m_32b_ar_slot_p5s_ready), .rd_data(p4m_32b_ar_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_32b_ar_slot_p5s_in_valid = p5m_32b_ar_to_p5s && p5m_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_p5m_32b_ar_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_32b_ar_slot_p5s_in_valid), .wr_ready(p5m_32b_ar_slot_p5s_in_ready), .wr_data(p5m_32b_ar),
        .rd_valid(p5m_32b_ar_slot_p5s_valid), .rd_ready(p5m_32b_ar_slot_p5s_ready), .rd_data(p5m_32b_ar_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_32b_ar_slot_p5s_in_valid = wbm_32b_ar_to_p5s && wbm_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_wbm_32b_ar_slot_p5s (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_32b_ar_slot_p5s_in_valid), .wr_ready(wbm_32b_ar_slot_p5s_in_ready), .wr_data(wbm_32b_ar),
        .rd_valid(wbm_32b_ar_slot_p5s_valid), .rd_ready(wbm_32b_ar_slot_p5s_ready), .rd_data(wbm_32b_ar_slot_p5s),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for p5s: round-robin, lock until handshake ----
    logic [5:0] p5s_ar_arb_req;
    assign p5s_ar_arb_req = {wbm_32b_ar_slot_p5s_valid, p5m_32b_ar_slot_p5s_valid, p4m_32b_ar_slot_p5s_valid, l5m_32b_ar_slot_p5s_valid, l4m_32b_ar_slot_p5s_valid, cpu_32b_ar_slot_p5s_valid};
    logic [2:0] p5s_ar_arb_lock, p5s_ar_arb_rr;
    logic p5s_ar_arb_locked;
    wire [2:0] p5s_ar_arb_pick = (p5s_ar_arb_rr == 3'd0) ? (p5s_ar_arb_req[0] ? 3'd0 : p5s_ar_arb_req[1] ? 3'd1 : p5s_ar_arb_req[2] ? 3'd2 : p5s_ar_arb_req[3] ? 3'd3 : p5s_ar_arb_req[4] ? 3'd4 : 3'd5) : 
        (p5s_ar_arb_rr == 3'd1) ? (p5s_ar_arb_req[1] ? 3'd1 : p5s_ar_arb_req[2] ? 3'd2 : p5s_ar_arb_req[3] ? 3'd3 : p5s_ar_arb_req[4] ? 3'd4 : p5s_ar_arb_req[5] ? 3'd5 : 3'd0) : 
        (p5s_ar_arb_rr == 3'd2) ? (p5s_ar_arb_req[2] ? 3'd2 : p5s_ar_arb_req[3] ? 3'd3 : p5s_ar_arb_req[4] ? 3'd4 : p5s_ar_arb_req[5] ? 3'd5 : p5s_ar_arb_req[0] ? 3'd0 : 3'd1) : 
        (p5s_ar_arb_rr == 3'd3) ? (p5s_ar_arb_req[3] ? 3'd3 : p5s_ar_arb_req[4] ? 3'd4 : p5s_ar_arb_req[5] ? 3'd5 : p5s_ar_arb_req[0] ? 3'd0 : p5s_ar_arb_req[1] ? 3'd1 : 3'd2) : 
        (p5s_ar_arb_rr == 3'd4) ? (p5s_ar_arb_req[4] ? 3'd4 : p5s_ar_arb_req[5] ? 3'd5 : p5s_ar_arb_req[0] ? 3'd0 : p5s_ar_arb_req[1] ? 3'd1 : p5s_ar_arb_req[2] ? 3'd2 : 3'd3) : 
        p5s_ar_arb_req[5] ? 3'd5 : p5s_ar_arb_req[0] ? 3'd0 : p5s_ar_arb_req[1] ? 3'd1 : p5s_ar_arb_req[2] ? 3'd2 : p5s_ar_arb_req[3] ? 3'd3 : 3'd4;
    wire p5s_ar_arb_gnt_valid = p5s_ar_arb_locked || (|p5s_ar_arb_req);
    wire [2:0] p5s_ar_arb_gnt = p5s_ar_arb_locked ? p5s_ar_arb_lock : p5s_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            p5s_ar_arb_lock   <= '0;
            p5s_ar_arb_rr     <= '0;
            p5s_ar_arb_locked <= 1'b0;
        end else begin
            if (p5s_axi_arvalid && p5s_axi_arready) begin
                p5s_ar_arb_locked <= 1'b0;
                p5s_ar_arb_rr <= (p5s_ar_arb_gnt == 3'd5) ? 3'd0 : p5s_ar_arb_gnt + 1'b1;
            end else if (p5s_axi_arvalid) begin
                p5s_ar_arb_lock   <= p5s_ar_arb_gnt;
                p5s_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_32b_ar_gnt_p5s = p5s_ar_arb_gnt_valid && (p5s_ar_arb_gnt == 3'd0) && p5s_ar_arb_req[0];
    wire l4m_32b_ar_gnt_p5s = p5s_ar_arb_gnt_valid && (p5s_ar_arb_gnt == 3'd1) && p5s_ar_arb_req[1];
    wire l5m_32b_ar_gnt_p5s = p5s_ar_arb_gnt_valid && (p5s_ar_arb_gnt == 3'd2) && p5s_ar_arb_req[2];
    wire p4m_32b_ar_gnt_p5s = p5s_ar_arb_gnt_valid && (p5s_ar_arb_gnt == 3'd3) && p5s_ar_arb_req[3];
    wire p5m_32b_ar_gnt_p5s = p5s_ar_arb_gnt_valid && (p5s_ar_arb_gnt == 3'd4) && p5s_ar_arb_req[4];
    wire wbm_32b_ar_gnt_p5s = p5s_ar_arb_gnt_valid && (p5s_ar_arb_gnt == 3'd5) && p5s_ar_arb_req[5];
    assign cpu_32b_ar_slot_p5s_ready = cpu_32b_ar_gnt_p5s && p5s_axi_arready;
    assign l4m_32b_ar_slot_p5s_ready = l4m_32b_ar_gnt_p5s && p5s_axi_arready;
    assign l5m_32b_ar_slot_p5s_ready = l5m_32b_ar_gnt_p5s && p5s_axi_arready;
    assign p4m_32b_ar_slot_p5s_ready = p4m_32b_ar_gnt_p5s && p5s_axi_arready;
    assign p5m_32b_ar_slot_p5s_ready = p5m_32b_ar_gnt_p5s && p5s_axi_arready;
    assign wbm_32b_ar_slot_p5s_ready = wbm_32b_ar_gnt_p5s && p5s_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign p5s_axi_arid = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.id : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.id : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.id : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.id : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.id : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.id : '0);
    assign p5s_axi_araddr = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.addr : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.addr : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.addr : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.addr : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.addr : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.addr : '0);
    assign p5s_axi_arlen = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.len : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.len : '0) |
