    assign p5s_axi_arburst = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.burst : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.burst : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.burst : '0) |
