    assign p5s_axi_arlock = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.lock : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.lock : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.lock : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.lock : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.lock : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.lock : '0);
    assign p5s_axi_arcache = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.cache : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.cache : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.cache : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.cache : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.cache : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.cache : '0);
    assign p5s_axi_arprot = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.prot : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.prot : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.prot : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.prot : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.prot : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.prot : '0);
    assign p5s_axi_arqos = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.qos : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.qos : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.qos : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.qos : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.qos : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.qos : '0);
    assign p5s_axi_arregion = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.region : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.region : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.region : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.region : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.region : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.region : '0);
    assign p5s_axi_aruser = (cpu_32b_ar_gnt_p5s ? cpu_32b_ar_slot_p5s.user : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_32b_ar_slot_p5s.user : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_32b_ar_slot_p5s.user : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_32b_ar_slot_p5s.user : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_32b_ar_slot_p5s.user : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_32b_ar_slot_p5s.user : '0);
    assign p5s_axi_arvalid = cpu_32b_ar_gnt_p5s || l4m_32b_ar_gnt_p5s || l5m_32b_ar_gnt_p5s || p4m_32b_ar_gnt_p5s || p5m_32b_ar_gnt_p5s || wbm_32b_ar_gnt_p5s;

    // Rready (slave -> the master whose response arbiter granted it)
    assign p5s_axi_rready = (cpu_32b_r_rgnt_p5s ? cpu_32b_rready : '0) |
        (l4m_32b_r_rgnt_p5s ? l4m_32b_rready : '0) |
        (l5m_32b_r_rgnt_p5s ? l5m_32b_rready : '0) |
        (p4m_32b_r_rgnt_p5s ? p4m_32b_rready : '0) |
        (p5m_32b_r_rgnt_p5s ? p5m_32b_rready : '0) |
        (wbm_32b_r_rgnt_p5s ? wbm_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign p5s_axi_bridge_id_ar = (cpu_32b_ar_gnt_p5s ? cpu_bridge_id_ar : '0) |
        (l4m_32b_ar_gnt_p5s ? l4m_bridge_id_ar : '0) |
        (l5m_32b_ar_gnt_p5s ? l5m_bridge_id_ar : '0) |
        (p4m_32b_ar_gnt_p5s ? p4m_bridge_id_ar : '0) |
        (p5m_32b_ar_gnt_p5s ? p5m_bridge_id_ar : '0) |
        (wbm_32b_ar_gnt_p5s ? wbm_bridge_id_ar : '0);


    // ================================================================
    // Slave 5: wbs (64b)
    // ================================================================
    // Multi-master (6 masters) → wbs
    //   - cpu (rw)
    //   - l4m (rw)
    //   - l5m (rw)
    //   - p4m (rw)
    //   - p5m (rw)
    //   - wbm (rw)

    wire cpu_64b_aw_to_wbs = ((cpu_64b_aw.addr >= 32'h50000000) && (cpu_64b_aw.addr <= 32'h50ffffff));
    wire cpu_64b_ar_to_wbs = ((cpu_64b_ar.addr >= 32'h50000000) && (cpu_64b_ar.addr <= 32'h50ffffff));
    wire l4m_64b_aw_to_wbs = ((l4m_64b_aw.addr >= 32'h50000000) && (l4m_64b_aw.addr <= 32'h50ffffff));
    wire l4m_64b_ar_to_wbs = ((l4m_64b_ar.addr >= 32'h50000000) && (l4m_64b_ar.addr <= 32'h50ffffff));
    wire l5m_64b_aw_to_wbs = ((l5m_64b_aw.addr >= 32'h50000000) && (l5m_64b_aw.addr <= 32'h50ffffff));
    wire l5m_64b_ar_to_wbs = ((l5m_64b_ar.addr >= 32'h50000000) && (l5m_64b_ar.addr <= 32'h50ffffff));
    wire p4m_64b_aw_to_wbs = ((p4m_64b_aw.addr >= 32'h50000000) && (p4m_64b_aw.addr <= 32'h50ffffff));
    wire p4m_64b_ar_to_wbs = ((p4m_64b_ar.addr >= 32'h50000000) && (p4m_64b_ar.addr <= 32'h50ffffff));
    wire p5m_64b_aw_to_wbs = ((p5m_64b_aw.addr >= 32'h50000000) && (p5m_64b_aw.addr <= 32'h50ffffff));
    wire p5m_64b_ar_to_wbs = ((p5m_64b_ar.addr >= 32'h50000000) && (p5m_64b_ar.addr <= 32'h50ffffff));
    wire wbm_64b_aw_to_wbs = ((wbm_64b_aw.addr >= 32'h50000000) && (wbm_64b_aw.addr <= 32'h50ffffff));
    wire wbm_64b_ar_to_wbs = ((wbm_64b_ar.addr >= 32'h50000000) && (wbm_64b_ar.addr <= 32'h50ffffff));

    // AW request slots for wbs: arbitration at the slave pins
    assign cpu_64b_aw_slot_wbs_in_valid = cpu_64b_aw_to_wbs && cpu_64b_awvalid && !(cpu_64b_aw_hold_wbs || cpu_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_wbs (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_aw_slot_wbs_in_valid), .wr_ready(cpu_64b_aw_slot_wbs_in_ready), .wr_data(cpu_64b_aw),
        .rd_valid(cpu_64b_aw_slot_wbs_valid), .rd_ready(cpu_64b_aw_slot_wbs_ready), .rd_data(cpu_64b_aw_slot_wbs),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l4m_64b_aw_slot_wbs_in_valid = l4m_64b_aw_to_wbs && l4m_64b_awvalid && !(l4m_64b_aw_hold_wbs || l4m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l4m_64b_aw_slot_wbs (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l4m_64b_aw_slot_wbs_in_valid), .wr_ready(l4m_64b_aw_slot_wbs_in_ready), .wr_data(l4m_64b_aw),
        .rd_valid(l4m_64b_aw_slot_wbs_valid), .rd_ready(l4m_64b_aw_slot_wbs_ready), .rd_data(l4m_64b_aw_slot_wbs),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign l5m_64b_aw_slot_wbs_in_valid = l5m_64b_aw_to_wbs && l5m_64b_awvalid && !(l5m_64b_aw_hold_wbs || l5m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_l5m_64b_aw_slot_wbs (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(l5m_64b_aw_slot_wbs_in_valid), .wr_ready(l5m_64b_aw_slot_wbs_in_ready), .wr_data(l5m_64b_aw),
        .rd_valid(l5m_64b_aw_slot_wbs_valid), .rd_ready(l5m_64b_aw_slot_wbs_ready), .rd_data(l5m_64b_aw_slot_wbs),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_64b_aw_slot_wbs_in_valid = p4m_64b_aw_to_wbs && p4m_64b_awvalid && !(p4m_64b_aw_hold_wbs || p4m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p4m_64b_aw_slot_wbs (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_64b_aw_slot_wbs_in_valid), .wr_ready(p4m_64b_aw_slot_wbs_in_ready), .wr_data(p4m_64b_aw),
        .rd_valid(p4m_64b_aw_slot_wbs_valid), .rd_ready(p4m_64b_aw_slot_wbs_ready), .rd_data(p4m_64b_aw_slot_wbs),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_64b_aw_slot_wbs_in_valid = p5m_64b_aw_to_wbs && p5m_64b_awvalid && !(p5m_64b_aw_hold_wbs || p5m_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_p5m_64b_aw_slot_wbs (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_64b_aw_slot_wbs_in_valid), .wr_ready(p5m_64b_aw_slot_wbs_in_ready), .wr_data(p5m_64b_aw),
        .rd_valid(p5m_64b_aw_slot_wbs_valid), .rd_ready(p5m_64b_aw_slot_wbs_ready), .rd_data(p5m_64b_aw_slot_wbs),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_64b_aw_slot_wbs_in_valid = wbm_64b_aw_to_wbs && wbm_64b_awvalid && !(wbm_64b_aw_hold_wbs || wbm_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_wbm_64b_aw_slot_wbs (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_64b_aw_slot_wbs_in_valid), .wr_ready(wbm_64b_aw_slot_wbs_in_ready), .wr_data(wbm_64b_aw),
        .rd_valid(wbm_64b_aw_slot_wbs_valid), .rd_ready(wbm_64b_aw_slot_wbs_ready), .rd_data(wbm_64b_aw_slot_wbs),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for wbs: round-robin, lock until handshake ----
    logic [5:0] wbs_aw_arb_req;
    assign wbs_aw_arb_req = {wbm_64b_aw_slot_wbs_valid, p5m_64b_aw_slot_wbs_valid, p4m_64b_aw_slot_wbs_valid, l5m_64b_aw_slot_wbs_valid, l4m_64b_aw_slot_wbs_valid, cpu_64b_aw_slot_wbs_valid};
    logic [2:0] wbs_aw_arb_lock, wbs_aw_arb_rr;
    logic wbs_aw_arb_locked;
    wire [2:0] wbs_aw_arb_pick = (wbs_aw_arb_rr == 3'd0) ? (wbs_aw_arb_req[0] ? 3'd0 : wbs_aw_arb_req[1] ? 3'd1 : wbs_aw_arb_req[2] ? 3'd2 : wbs_aw_arb_req[3] ? 3'd3 : wbs_aw_arb_req[4] ? 3'd4 : 3'd5) : 
        (wbs_aw_arb_rr == 3'd1) ? (wbs_aw_arb_req[1] ? 3'd1 : wbs_aw_arb_req[2] ? 3'd2 : wbs_aw_arb_req[3] ? 3'd3 : wbs_aw_arb_req[4] ? 3'd4 : wbs_aw_arb_req[5] ? 3'd5 : 3'd0) : 
        (wbs_aw_arb_rr == 3'd2) ? (wbs_aw_arb_req[2] ? 3'd2 : wbs_aw_arb_req[3] ? 3'd3 : wbs_aw_arb_req[4] ? 3'd4 : wbs_aw_arb_req[5] ? 3'd5 : wbs_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (wbs_aw_arb_rr == 3'd3) ? (wbs_aw_arb_req[3] ? 3'd3 : wbs_aw_arb_req[4] ? 3'd4 : wbs_aw_arb_req[5] ? 3'd5 : wbs_aw_arb_req[0] ? 3'd0 : wbs_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        (wbs_aw_arb_rr == 3'd4) ? (wbs_aw_arb_req[4] ? 3'd4 : wbs_aw_arb_req[5] ? 3'd5 : wbs_aw_arb_req[0] ? 3'd0 : wbs_aw_arb_req[1] ? 3'd1 : wbs_aw_arb_req[2] ? 3'd2 : 3'd3) : 
        wbs_aw_arb_req[5] ? 3'd5 : wbs_aw_arb_req[0] ? 3'd0 : wbs_aw_arb_req[1] ? 3'd1 : wbs_aw_arb_req[2] ? 3'd2 : wbs_aw_arb_req[3] ? 3'd3 : 3'd4;
    wire wbs_aw_arb_gnt_valid = wbs_aw_arb_locked || (|wbs_aw_arb_req);
    wire [2:0] wbs_aw_arb_gnt = wbs_aw_arb_locked ? wbs_aw_arb_lock : wbs_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            wbs_aw_arb_lock   <= '0;
            wbs_aw_arb_rr     <= '0;
            wbs_aw_arb_locked <= 1'b0;
        end else begin
            if (wbs_axi_awvalid && wbs_axi_awready) begin
                wbs_aw_arb_locked <= 1'b0;
                wbs_aw_arb_rr <= (wbs_aw_arb_gnt == 3'd5) ? 3'd0 : wbs_aw_arb_gnt + 1'b1;
            end else if (wbs_axi_awvalid) begin
                wbs_aw_arb_lock   <= wbs_aw_arb_gnt;
                wbs_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_aw_gnt_wbs = wbs_aw_arb_gnt_valid && (wbs_aw_arb_gnt == 3'd0) && wbs_aw_arb_req[0];
    wire l4m_64b_aw_gnt_wbs = wbs_aw_arb_gnt_valid && (wbs_aw_arb_gnt == 3'd1) && wbs_aw_arb_req[1];
    wire l5m_64b_aw_gnt_wbs = wbs_aw_arb_gnt_valid && (wbs_aw_arb_gnt == 3'd2) && wbs_aw_arb_req[2];
    wire p4m_64b_aw_gnt_wbs = wbs_aw_arb_gnt_valid && (wbs_aw_arb_gnt == 3'd3) && wbs_aw_arb_req[3];
    wire p5m_64b_aw_gnt_wbs = wbs_aw_arb_gnt_valid && (wbs_aw_arb_gnt == 3'd4) && wbs_aw_arb_req[4];
    wire wbm_64b_aw_gnt_wbs = wbs_aw_arb_gnt_valid && (wbs_aw_arb_gnt == 3'd5) && wbs_aw_arb_req[5];
    assign cpu_64b_aw_slot_wbs_ready = cpu_64b_aw_gnt_wbs && wbs_axi_awready;
    assign l4m_64b_aw_slot_wbs_ready = l4m_64b_aw_gnt_wbs && wbs_axi_awready;
    assign l5m_64b_aw_slot_wbs_ready = l5m_64b_aw_gnt_wbs && wbs_axi_awready;
    assign p4m_64b_aw_slot_wbs_ready = p4m_64b_aw_gnt_wbs && wbs_axi_awready;
    assign p5m_64b_aw_slot_wbs_ready = p5m_64b_aw_gnt_wbs && wbs_axi_awready;
    assign wbm_64b_aw_slot_wbs_ready = wbm_64b_aw_gnt_wbs && wbs_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign wbs_axi_awid = (cpu_64b_aw_gnt_wbs ? cpu_64b_aw_slot_wbs.id : '0) |
        (l4m_64b_aw_gnt_wbs ? l4m_64b_aw_slot_wbs.id : '0) |
        (l5m_64b_aw_gnt_wbs ? l5m_64b_aw_slot_wbs.id : '0) |
        (p4m_64b_aw_gnt_wbs ? p4m_64b_aw_slot_wbs.id : '0) |
        (p5m_64b_aw_gnt_wbs ? p5m_64b_aw_slot_wbs.id : '0) |
        (wbm_64b_aw_gnt_wbs ? wbm_64b_aw_slot_wbs.id : '0);
    assign wbs_axi_awaddr = (cpu_64b_aw_gnt_wbs ? cpu_64b_aw_slot_wbs.addr : '0) |
        (l4m_64b_aw_gnt_wbs ? l4m_64b_aw_slot_wbs.addr : '0) |
        (l5m_64b_aw_gnt_wbs ? l5m_64b_aw_slot_wbs.addr : '0) |
        (p4m_64b_aw_gnt_wbs ? p4m_64b_aw_slot_wbs.addr : '0) |
        (p5m_64b_aw_gnt_wbs ? p5m_64b_aw_slot_wbs.addr : '0) |
        (wbm_64b_aw_gnt_wbs ? wbm_64b_aw_slot_wbs.addr : '0);
    assign wbs_axi_awlen = (cpu_64b_aw_gnt_wbs ? cpu_64b_aw_slot_wbs.len : '0) |
        (l4m_64b_aw_gnt_wbs ? l4m_64b_aw_slot_wbs.len : '0) |
        (l5m_64b_aw_gnt_wbs ? l5m_64b_aw_slot_wbs.len : '0) |
        (p4m_64b_aw_gnt_wbs ? p4m_64b_aw_slot_wbs.len : '0) |
        (p5m_64b_aw_gnt_wbs ? p5m_64b_aw_slot_wbs.len : '0) |
        (wbm_64b_aw_gnt_wbs ? wbm_64b_aw_slot_wbs.len : '0);
    assign wbs_axi_awsize = (cpu_64b_aw_gnt_wbs ? cpu_64b_aw_slot_wbs.size : '0) |
        (l4m_64b_aw_gnt_wbs ? l4m_64b_aw_slot_wbs.size : '0) |
        (l5m_64b_aw_gnt_wbs ? l5m_64b_aw_slot_wbs.size : '0) |
