        (subtractive_aw_arb_rr == 3'd2) ? (subtractive_aw_arb_req[2] ? 3'd2 : subtractive_aw_arb_req[3] ? 3'd3 : subtractive_aw_arb_req[4] ? 3'd4 : subtractive_aw_arb_req[5] ? 3'd5 : subtractive_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (subtractive_aw_arb_rr == 3'd3) ? (subtractive_aw_arb_req[3] ? 3'd3 : subtractive_aw_arb_req[4] ? 3'd4 : subtractive_aw_arb_req[5] ? 3'd5 : subtractive_aw_arb_req[0] ? 3'd0 : subtractive_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        (subtractive_aw_arb_rr == 3'd4) ? (subtractive_aw_arb_req[4] ? 3'd4 : subtractive_aw_arb_req[5] ? 3'd5 : subtractive_aw_arb_req[0] ? 3'd0 : subtractive_aw_arb_req[1] ? 3'd1 : subtractive_aw_arb_req[2] ? 3'd2 : 3'd3) : 
        subtractive_aw_arb_req[5] ? 3'd5 : subtractive_aw_arb_req[0] ? 3'd0 : subtractive_aw_arb_req[1] ? 3'd1 : subtractive_aw_arb_req[2] ? 3'd2 : subtractive_aw_arb_req[3] ? 3'd3 : 3'd4;
    wire subtractive_aw_arb_gnt_valid = subtractive_aw_arb_locked || (|subtractive_aw_arb_req);
    wire [2:0] subtractive_aw_arb_gnt = subtractive_aw_arb_locked ? subtractive_aw_arb_lock : subtractive_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_aw_arb_lock   <= '0;
            subtractive_aw_arb_rr     <= '0;
            subtractive_aw_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_awvalid && subtractive_axi_awready) begin
