    )
    wire cpu_64b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd0) && subtractive_aw_arb_req[0];
    wire l4m_64b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd1) && subtractive_aw_arb_req[1];
    wire l5m_64b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd2) && subtractive_aw_arb_req[2];
    wire p4m_64b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd3) && subtractive_aw_arb_req[3];
    wire p5m_64b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd4) && subtractive_aw_arb_req[4];
    wire wbm_64b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd5) && subtractive_aw_arb_req[5];
    assign cpu_64b_aw_slot_subtractive_ready = cpu_64b_aw_gnt_subtractive && subtractive_axi_awready;
    assign l4m_64b_aw_slot_subtractive_ready = l4m_64b_aw_gnt_subtractive && subtractive_axi_awready;
