    assign p4m_64b_aw_slot_subtractive_ready = p4m_64b_aw_gnt_subtractive && subtractive_axi_awready;
    assign p5m_64b_aw_slot_subtractive_ready = p5m_64b_aw_gnt_subtractive && subtractive_axi_awready;
