        (l5m_64b_aw_gnt_subtractive ? l5m_64b_aw_slot_subtractive.size : '0) |
        (p4m_64b_aw_gnt_subtractive ? p4m_64b_aw_slot_subtractive.size : '0) |
        (p5m_64b_aw_gnt_subtractive ? p5m_64b_aw_slot_subtractive.size : '0) |
