        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p4m_64b_ar_slot_subtractive_in_valid = p4m_64b_ar_to_subtractive && p4m_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_p4m_64b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p4m_64b_ar_slot_subtractive_in_valid), .wr_ready(p4m_64b_ar_slot_subtractive_in_ready), .wr_data(p4m_64b_ar),
        .rd_valid(p4m_64b_ar_slot_subtractive_valid), .rd_ready(p4m_64b_ar_slot_subtractive_ready), .rd_data(p4m_64b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign p5m_64b_ar_slot_subtractive_in_valid = p5m_64b_ar_to_subtractive && p5m_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_p5m_64b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(p5m_64b_ar_slot_subtractive_in_valid), .wr_ready(p5m_64b_ar_slot_subtractive_in_ready), .wr_data(p5m_64b_ar),
        .rd_valid(p5m_64b_ar_slot_subtractive_valid), .rd_ready(p5m_64b_ar_slot_subtractive_ready), .rd_data(p5m_64b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign wbm_64b_ar_slot_subtractive_in_valid = wbm_64b_ar_to_subtractive && wbm_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_wbm_64b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_64b_ar_slot_subtractive_in_valid), .wr_ready(wbm_64b_ar_slot_subtractive_in_ready), .wr_data(wbm_64b_ar),
        .rd_valid(wbm_64b_ar_slot_subtractive_valid), .rd_ready(wbm_64b_ar_slot_subtractive_ready), .rd_data(wbm_64b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for subtractive: round-robin, lock until handshake ----
    logic [5:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {wbm_64b_ar_slot_subtractive_valid, p5m_64b_ar_slot_subtractive_valid, p4m_64b_ar_slot_subtractive_valid, l5m_64b_ar_slot_subtractive_valid, l4m_64b_ar_slot_subtractive_valid, cpu_64b_ar_slot_subtractive_valid};
    logic [2:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    wire [2:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 3'd0) ? (subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : 3'd5) : 
        (subtractive_ar_arb_rr == 3'd1) ? (subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[5] ? 3'd5 : 3'd0) : 
        (subtractive_ar_arb_rr == 3'd2) ? (subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[5] ? 3'd5 : subtractive_ar_arb_req[0] ? 3'd0 : 3'd1) : 
        (subtractive_ar_arb_rr == 3'd3) ? (subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[5] ? 3'd5 : subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : 3'd2) : 
        (subtractive_ar_arb_rr == 3'd4) ? (subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[5] ? 3'd5 : subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : 3'd3) : 
        subtractive_ar_arb_req[5] ? 3'd5 : subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : 3'd4;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [2:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_arvalid && subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 3'd5) ? 3'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd0) && subtractive_ar_arb_req[0];
    wire l4m_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd1) && subtractive_ar_arb_req[1];
    wire l5m_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd2) && subtractive_ar_arb_req[2];
    wire p4m_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd3) && subtractive_ar_arb_req[3];
    wire p5m_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd4) && subtractive_ar_arb_req[4];
    wire wbm_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd5) && subtractive_ar_arb_req[5];
    assign cpu_64b_ar_slot_subtractive_ready = cpu_64b_ar_gnt_subtractive && subtractive_axi_arready;
    assign l4m_64b_ar_slot_subtractive_ready = l4m_64b_ar_gnt_subtractive && subtractive_axi_arready;
    assign l5m_64b_ar_slot_subtractive_ready = l5m_64b_ar_gnt_subtractive && subtractive_axi_arready;
    assign p4m_64b_ar_slot_subtractive_ready = p4m_64b_ar_gnt_subtractive && subtractive_axi_arready;
    assign p5m_64b_ar_slot_subtractive_ready = p5m_64b_ar_gnt_subtractive && subtractive_axi_arready;
    assign wbm_64b_ar_slot_subtractive_ready = wbm_64b_ar_gnt_subtractive && subtractive_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign subtractive_axi_arid = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.id : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.id : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.id : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.id : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.id : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.id : '0);
    assign subtractive_axi_araddr = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.addr : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.addr : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.addr : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.addr : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.addr : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.addr : '0);
    assign subtractive_axi_arlen = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.len : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.len : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.len : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.len : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.len : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.len : '0);
    assign subtractive_axi_arsize = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.size : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.size : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.size : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.size : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.size : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.size : '0);
    assign subtractive_axi_arburst = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.burst : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.burst : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.burst : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.burst : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.burst : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.burst : '0);
    assign subtractive_axi_arlock = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.lock : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.lock : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.lock : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.lock : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.lock : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.lock : '0);
    assign subtractive_axi_arcache = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.cache : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.cache : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.cache : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.cache : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.cache : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.cache : '0);
    assign subtractive_axi_arprot = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.prot : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.prot : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.prot : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.prot : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.prot : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.prot : '0);
    assign subtractive_axi_arqos = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.qos : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.qos : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.qos : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.qos : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.qos : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.qos : '0);
    assign subtractive_axi_arregion = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.region : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.region : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.region : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.region : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.region : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.region : '0);
    assign subtractive_axi_aruser = (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.user : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_64b_ar_slot_subtractive.user : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_64b_ar_slot_subtractive.user : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_64b_ar_slot_subtractive.user : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_64b_ar_slot_subtractive.user : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.user : '0);
    assign subtractive_axi_arvalid = cpu_64b_ar_gnt_subtractive || l4m_64b_ar_gnt_subtractive || l5m_64b_ar_gnt_subtractive || p4m_64b_ar_gnt_subtractive || p5m_64b_ar_gnt_subtractive || wbm_64b_ar_gnt_subtractive;

    // Rready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_rready = (cpu_64b_r_rgnt_subtractive ? cpu_64b_rready : '0) |
        (l4m_64b_r_rgnt_subtractive ? l4m_64b_rready : '0) |
        (l5m_64b_r_rgnt_subtractive ? l5m_64b_rready : '0) |
        (p4m_64b_r_rgnt_subtractive ? p4m_64b_rready : '0) |
        (p5m_64b_r_rgnt_subtractive ? p5m_64b_rready : '0) |
        (wbm_64b_r_rgnt_subtractive ? wbm_64b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign subtractive_axi_bridge_id_ar = (cpu_64b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0) |
        (l4m_64b_ar_gnt_subtractive ? l4m_bridge_id_ar : '0) |
        (l5m_64b_ar_gnt_subtractive ? l5m_bridge_id_ar : '0) |
        (p4m_64b_ar_gnt_subtractive ? p4m_bridge_id_ar : '0) |
        (p5m_64b_ar_gnt_subtractive ? p5m_bridge_id_ar : '0) |
        (wbm_64b_ar_gnt_subtractive ? wbm_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // cpu 32b path -> l4s, p4s, p5s (16 deep: max_outstanding)
    logic [1:0] cpu_32b_wdest_mem [16];
    logic [4:0] cpu_32b_wdest_wptr, cpu_32b_wdest_rptr;
    wire [1:0] cpu_32b_wdest_enc = cpu_32b_aw_to_p4s ? 2'd1 : cpu_32b_aw_to_p5s ? 2'd2 : 2'd0;
    wire cpu_32b_wdest_push = cpu_32b_awvalid && cpu_32b_awready;
    wire cpu_32b_wdest_pop  = cpu_32b_wvalid && cpu_32b_wready && cpu_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_wdest_wptr <= '0;
            cpu_32b_wdest_rptr <= '0;
        end else begin
            if (cpu_32b_wdest_push) begin
                cpu_32b_wdest_mem[cpu_32b_wdest_wptr[3:0]] <= cpu_32b_wdest_enc;
                cpu_32b_wdest_wptr <= cpu_32b_wdest_wptr + 1'b1;
            end
            if (cpu_32b_wdest_pop) begin
                cpu_32b_wdest_rptr <= cpu_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_32b_wdest_valid = (cpu_32b_wdest_wptr != cpu_32b_wdest_rptr);
    assign cpu_32b_wdest_full = (cpu_32b_wdest_wptr[4] != cpu_32b_wdest_rptr[4]) && (cpu_32b_wdest_wptr[3:0] == cpu_32b_wdest_rptr[3:0]);
    wire [1:0] cpu_32b_wdest_head = cpu_32b_wdest_mem[cpu_32b_wdest_rptr[3:0]];
    assign cpu_32b_w_to_l4s = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd0);
    assign cpu_32b_w_to_p4s = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd1);
    assign cpu_32b_w_to_p5s = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd2);

    // cpu 64b path -> mem, l5s, wbs, subtractive (16 deep: max_outstanding)
    logic [1:0] cpu_64b_wdest_mem [16];
    logic [4:0] cpu_64b_wdest_wptr, cpu_64b_wdest_rptr;
    wire [1:0] cpu_64b_wdest_enc = cpu_64b_aw_to_l5s ? 2'd1 : cpu_64b_aw_to_wbs ? 2'd2 : cpu_64b_aw_to_subtractive ? 2'd3 : 2'd0;
    wire cpu_64b_wdest_push = cpu_64b_awvalid && cpu_64b_awready;
    wire cpu_64b_wdest_pop  = cpu_64b_wvalid && cpu_64b_wready && cpu_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_64b_wdest_wptr <= '0;
            cpu_64b_wdest_rptr <= '0;
        end else begin
            if (cpu_64b_wdest_push) begin
                cpu_64b_wdest_mem[cpu_64b_wdest_wptr[3:0]] <= cpu_64b_wdest_enc;
                cpu_64b_wdest_wptr <= cpu_64b_wdest_wptr + 1'b1;
            end
            if (cpu_64b_wdest_pop) begin
                cpu_64b_wdest_rptr <= cpu_64b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_64b_wdest_valid = (cpu_64b_wdest_wptr != cpu_64b_wdest_rptr);
    assign cpu_64b_wdest_full = (cpu_64b_wdest_wptr[4] != cpu_64b_wdest_rptr[4]) && (cpu_64b_wdest_wptr[3:0] == cpu_64b_wdest_rptr[3:0]);
    wire [1:0] cpu_64b_wdest_head = cpu_64b_wdest_mem[cpu_64b_wdest_rptr[3:0]];
    assign cpu_64b_w_to_mem = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd0);
    assign cpu_64b_w_to_l5s = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd1);
    assign cpu_64b_w_to_wbs = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd2);
    assign cpu_64b_w_to_subtractive = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd3);

    // l4m 32b path -> l4s, p4s, p5s (16 deep: max_outstanding)
    logic [1:0] l4m_32b_wdest_mem [16];
    logic [4:0] l4m_32b_wdest_wptr, l4m_32b_wdest_rptr;
    wire [1:0] l4m_32b_wdest_enc = l4m_32b_aw_to_p4s ? 2'd1 : l4m_32b_aw_to_p5s ? 2'd2 : 2'd0;
    wire l4m_32b_wdest_push = l4m_32b_awvalid && l4m_32b_awready;
    wire l4m_32b_wdest_pop  = l4m_32b_wvalid && l4m_32b_wready && l4m_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            l4m_32b_wdest_wptr <= '0;
            l4m_32b_wdest_rptr <= '0;
        end else begin
            if (l4m_32b_wdest_push) begin
                l4m_32b_wdest_mem[l4m_32b_wdest_wptr[3:0]] <= l4m_32b_wdest_enc;
                l4m_32b_wdest_wptr <= l4m_32b_wdest_wptr + 1'b1;
            end
            if (l4m_32b_wdest_pop) begin
                l4m_32b_wdest_rptr <= l4m_32b_wdest_rptr + 1'b1;
            end
        end
    )
